    const HAJJ_STEPS = ['Намерение и ихрам','Микат','Таваф','Са‘и','Арафат','Муздалифа','Мина','Побитие камней','Жертвоприношение','Халяк/таксар','Таваф ифада','Таваф прощания'];

    const HAJJ_ORDER_STEPS = [
      { t: '1. Намерение и ихрам', tKk: '1. Ниет және ихрам',
        d: 'Намерение (ния) совершить хадж или умру ради Аллаха — сердцем, произносить вслух не обязательно. Мужчины надевают два несшитых белых полотнища (изар и рида) и сандалии; женщины — обычную скромную одежду любого цвета, без никаба и перчаток. Перед ихрамом желательно: гусль, стрижка ногтей и лишних волос, умащение тела благовониями (до намерения, не после), два ракаата (если не запретное время). Произносится тальбия: «Ляббайка Аллахумма ляббайк, ляббайка ля шарика ляка ляббайк…» — мужчины вслух, женщины негромко, повторяют часто до начала тавафа (в умре) или до побития камней в Мине (в хадже).\n\nХадис (Бухари 1): «Дела оцениваются только по намерениям» — напоминание, что даже внешние атрибуты ихрама (одежда, тальбия) без искреннего намерения ради Аллаха не превращают действие в акт поклонения. Ихрам — это прежде всего состояние сердца, вступление в которое налагает временные ограничения вплоть до выхода из него.\n\nПрактика: определить заранее вид хаджа (ифрад/таматту‘/кыран, см. вкладку «Виды») и не откладывать произнесение тальбии после надевания ихрама — по сунне она звучит сразу.\n\nРазличия между мазхабами: ханафиты и маликиты не считают благовония, нанесённые до ихрама, но оставшиеся на теле после его начала, нарушением, и шафииты с ханбалитами также разрешают это, если аромат был нанесён до намерения. Женщинам разрешено входить в ихрам даже во время месячных или послеродового кровотечения (хайд/нифас) — от них требуется лишь воздержаться от тавафа до очищения, всё остальное (тальбия, стояние на Арафате, побитие камней) выполняется как обычно. Путешествующим с пересадками важно уточнить маршрут заранее: если самолёт летит через территорию, отличную от объявленного миката, нужно ориентироваться по факту пролёта конкретной географической границы, а не по объявлению стюардов.',
        dKk: 'Ниет (ния) — Аллаһ үшін хадж немесе умра жасауды жүрекпен ниет ету, дауыстап айту міндетті емес. Ерлер тігілмеген екі ақ мата (изар мен рида) және сандал киеді; нәзік жандылар — кез келген түстегі әдепті, қарапайым киім, нікабсыз, қолғапсыз. Ихрамға дейін: ғұсыл алу, тырнақ пен артық шашты алу, денеге хош иіс жағу (ниет алдында, кейін емес), тыйым салынған уақыт болмаса екі рәкат намаз ұсынылады. Тәлбия айтылады: «Ляббайка Аллаһумма ляббайк, ляббайка ля шарика ляка ляббайк…» — ерлер дауыстап, нәзік жандылар жайлап, умрада тауаф басталғанға дейін, хажда тас лақтырғанға дейін жиі қайталайды.\n\nХадис (Бухари 1): «Іс-әрекеттер тек ниетке қарай бағаланады» — ихрамның сыртқы белгілері (киім, тәлбия) де, егер Аллаһ үшін шынайы ниет болмаса, әрекетті құлшылық актісіне айналдырмайтынын еске салады. Ихрам — ең алдымен жүрек күйі, оған кіру уақытша шектеулерді жүктейді, олар одан шыққанға дейін сақталады.\n\nТәжірибе: хаждың түрін (ифрад/таматту‘/қыран, «Түрлері» қойындысын қараңыз) алдын ала белгілеп алыңыз және ихрам киген соң тәлбияны айтуды кейінге қалдырмаңыз — сүннет бойынша ол бірден айтылады.\n\nМазхабтар арасындағы айырмашылықтар: ханафи және малики мазхабтары ихрамға дейін жағылған, бірақ ихрам басталғаннан кейін де денеде қалған хош иісті бұзушылық деп санамайды, ал шафии мен ханбали мазхабтары да иіс ниет алдында жағылған болса, оны рұқсат етеді. Нәзік жандыларға хайыз немесе нифас кезінде де ихрамға кіруге рұқсат етіледі — олардан тек тазарғанға дейін тауафтан бас тарту талап етіледі, қалғанының бәрі (тәлбия, Арафатта тұру, тас лақтыру) әдеттегідей орындалады. Ұшу барысында ауысулары бар саяхатшыларға маршрутты алдын ала нақтылау маңызды: егер ұшақ жарияланған микаттан басқа аумақ арқылы ұшса, стюарттардың хабарламасына емес, нақты географиялық шекараның өтуіне бағдарлану керек.' },
      { t: '2. Микат', tKk: '2. Микат',
        d: 'Граница на пути к Мекке, которую нельзя пересекать без ихрама тому, кто едет на хадж/умру. Пять главных микатов: Зуль-Хулейфа/Абьяр Али (для едущих из Медины), Джухфа/Рабиг (с запада — Египет, Шам), Йалямлям (с юга — Йемен), Карн аль-Маназиль/Ас-Сайль (с востока — Неджд), Зат-Ирк (с северо-востока — Ирак). Кто летит самолётом, обычно надевает ихрам до пролёта над линией миката (объявляется в салоне) либо в аэропорту вылета. Живущие в Джидде и внутри границ микатов надевают ихрам из дома или места проживания.\n\nХадис (Бухари 1526, Муслим 1181): Пророк ﷺ установил микаты для жителей соответствующих направлений и для всех, кто идёт через них с намерением хаджа или умры, «даже если они не из их числа». Пересечение миката без ихрама при таком намерении — нарушение, требующее вернуться к линии миката или заплатить фидью, если возвращение уже невозможно.\n\nПрактика: заранее уточнить у авиакомпании или группы, когда самолёт пролетает над линией миката, и надеть ихрам чуть раньше, с запасом.\n\nСовременные уточнения: для жителей Джидды действует особый статус — большинство современных учёных (в т.ч. Постоянный комитет КСА) считают Джидду находящейся внутри границ миката, поэтому её жители могут входить в ихрам из дома. Кто пересёк микат без ихрама по незнанию или не планируя заранее хадж/умру, но затем решил их совершить, надевает ихрам с того места, где принял решение, без обязательства возвращаться к линии миката. Взявшим одежду ихрама «про запас» на будущее не нужно ничего менять в микате — важна именно фактическая ния (намерение) в момент пересечения границы.',
        dKk: 'Меккеге бара жатқанда ихрамсыз өтуге болмайтын шекара. Бес негізгі микат: Зул-Хулейфа/Әбьяр Әли (Мәдинадан келетіндерге), Жухфа/Рабиғ (батыстан — Мысыр, Шам), Йаләмләм (оңтүстіктен — Йемен), Қарн әл-Маназил/Әс-Сәйл (шығыстан — Нежд), Зат-Ирк (солтүстік-шығыстан — Ирак). Ұшақпен ұшатындар әдетте микат сызығынан өтпей тұрып (салонда хабарланады) немесе ұшу аэропортында ихрам киеді. Джидда мен микат шекараларының ішінде тұратындар үйінен немесе тұрғылықты жерінен ихрам киеді.\n\nХадис (Бухари 1526, Мүслім 1181): Пайғамбар ﷺ тиісті бағыттардың тұрғындары үшін және хадж немесе умра ниетімен сол жерлерден өтетін барлық адамдар үшін, «тіпті олардың тұрғыны болмаса да», микаттарды белгіледі. Мұндай ниетпен микатты ихрамсыз кесіп өту — бұзушылық, микат сызығына қайта оралуды немесе қайту мүмкін болмаса, фидия төлеуді талап етеді.\n\nТәжірибе: ұшақ микат сызығынан қашан өтетінін әуе компаниясынан немесе топтан алдын ала нақтылап, ихрамды сәл ертерек, қорымен киіңіз.\n\nЗаманауи нақтылаулар: Джидда тұрғындарына арнайы мәртебе қолданылады — қазіргі ғалымдардың көпшілігі (соның ішінде ССК-ның Тұрақты комитеті) Джидданы микат шекарасының ішінде деп есептейді, сондықтан оның тұрғындары үйінен ихрам киюге болады. Микатты ихрамсыз білместікпен немесе хадж/умраны алдын ала жоспарламай өткен, бірақ кейін оларды жасауды шешкен адам, микат сызығына оралу міндетінсіз, шешім қабылдаған жерден ихрам киеді. Болашаққа «қор ретінде» ихрам алып жүргендерге микатта ештеңені өзгертудің қажеті жоқ — маңыздысы шекарадан өткен сәттегі нақты ниет (ния).' },
      { t: '3. Таваф (обход Каабы)', tKk: '3. Тауаф (Қағбаны айналу)',
        d: 'Семь кругов вокруг Каабы против часовой стрелки, Кааба остаётся слева. Начало и конец каждого круга — от линии Чёрного камня (истилям — поцелуй, касание рукой или жест издалека при давке, без давки и толчков). Мужчины в первых трёх кругах тавафа прибытия (кудум) ускоряют шаг (рамаль), в остальных идут обычным шагом; женщины идут обычным шагом всегда. Виды тавафа: кудум (прибытия, необязательный), умры (столп умры), ифада (столп хаджа), вада‘ (прощания). Желательны два ракаата за Макам Ибрахима после тавафа, если позволяет место.\n\nХадис (Бухари 1597): Умар (р.а.), целуя Чёрный камень, сказал: «Я знаю, что ты — камень, не приносящий ни вреда, ни пользы, и если бы я не видел, как Пророк ﷺ целовал тебя, я бы не стал этого делать» — целование камня не является поклонением ему самому, а лишь следованием сунне.\n\nПрактика: при большой давке не рисковать здоровьем ради касания камня — достаточно указать на него рукой издалека и продолжить обход.\n\nУсловия действительности тавафа: омовение (вуду), чистота тела и одежды от наджасы, покрытие аврата, точное начало и завершение каждого круга от линии Чёрного камня, все семь кругов — внутри мечети (включая новые расширенные этажи, но не за пределами внешних стен). Если человек усомнился в числе кругов, по умолчанию принимается меньшее число («уверенность не устраняется сомнением»). Ханафитский мазхаб не считает вуду строгим условием действительности тавафа (лишь ваджибом, нарушение которого искупается жертвой), тогда как три других мазхаба считают его шарт сихха — без вуду таваф придётся повторить.',
        dKk: 'Қағбаны сағат тілінің бағытына қарсы жеті рет айналу, Қағба сол жақта қалады. Әр айналымның басы мен соңы — Қара тас (Хажар әл-Асуад) сызығынан (истилям — сүю, қолмен тию немесе қалыпты болмаса алыстан белгі беру, түртіспей, итермей). Ерлер кудум (келу) тауафының алғашқы үш айналымында жылдамырақ жүреді (рамаль), қалғанында әдеттегідей; нәзік жандылар әрдайым қалыпты қадаммен жүреді. Тауаф түрлері: кудум (келу, парыз емес), умра тауафы (умраның тірегі), ифада (хаждың тірегі), уада‘ (қоштасу). Орын болса, тауафтан кейін Мақам Ибраһимнің артында екі рәкат намаз оқу ұсынылады.\n\nХадис (Бухари 1597): Омар (р.а.) Қара тасты сүйіп жатып: «Мен сенің зиян да, пайда да келтірмейтін тас екеніңді білемін, егер Пайғамбардың ﷺ сені сүйгенін көрмегенімде, мен де сүймес едім» деген — тасты сүю оның өзіне құлшылық ету емес, тек сүннетке еру.\n\nТәжірибе: қатты кептеліс кезінде тасқа тию үшін денсаулыққа қауіп төндірмеңіз — алыстан қолмен белгі беріп, айналуды жалғастыру жеткілікті.\n\nТауафтың жарамдылық шарттары: дәрет алу, дене мен киімнің нәжістен таза болуы, ауыратты жабу, әр айналымның Қара тас сызығынан дәл басталып, дәл аяқталуы, барлық жеті айналымның мешіт ішінде (жаңа кеңейтілген қабаттарды қоса, бірақ сыртқы қабырғалардан тыс емес) өтуі. Айналым санына күмән туса, әдепкі бойынша аз сан қабылданады («сенімділік күмәнмен жойылмайды» қағидасы). Ханафи мазхабы дәретті тауафтың қатаң жарамдылық шарты деп санамайды (тек уәжіп деп, бұзылуы құрбандықпен өтеледі), ал қалған үш мазхаб оны шарт сихха деп есептейді — дәретсіз тауафты қайталау керек болады.' },
      { t: '4. Са‘и (Сафа и Марва)', tKk: '4. Сағи (Сафа мен Марва)',
        d: 'Семь отрезков между холмами Сафа и Марва, начиная с Сафы и заканчивая на Марве (счёт: туда — 1, обратно — 2, и т.д.). Вспоминают, как Хаджар (мать Исмаиля) бегала в поисках воды, пока не забил источник Замзам. На участке между двумя зелёными отметками мужчинам желательно ускорить шаг (рамаль); женщины идут обычным шагом. После са‘и умры — укорачивание волос (для мужчин можно и бритьё, предпочтительнее) или подрезание концов (для женщин — на длину фаланги пальца), после чего выходят из ихрама умры (для совершающих таматту‘).\n\nОснова обряда — история Хаджар, матери пророка Исмаиля (мир ему): оставленная в безводной долине по велению Аллаха, она семь раз пробежала между холмами в поисках воды для сына, пока не забил источник Замзам у его ножек (хадис, Бухари 3364). Са‘и — это буквальное повторение её пути как напоминание, что усердие и упование на Аллаха не противоречат друг другу.\n\nПрактика: пить воду Замзам вдоволь во время и после са‘и — по сунне она пьётся стоя, лицом к Каабе, с дуа по своему намерению.\n\nУсловия: большинство учёных требуют, чтобы са‘и следовало за действительным тавафом (нельзя сделать са‘и раньше тавафа); ханбалиты допускают небольшую отсрочку между ними. Вуду для са‘и желательно, но, в отличие от тавафа, не обязательно — можно совершать его и без омовения. Использование инвалидных колясок или электрокаров на специальной дорожке допустимо для тех, кто не в силах идти сам; сопровождающий, толкающий коляску, совершает своё собственное са‘и одновременно, если у него самого есть такое намерение.',
        dKk: 'Сафа мен Марва төбелерінің арасындағы жеті аралық, Сафадан басталып, Марвада аяқталады (саны: барғанда — 1, қайтқанда — 2 т.б.). Хажар анамыздың (Исмаилдің анасы) су іздеп жүгіргені, Замзам бұлағы атқылағанша есте сақталады. Екі жасыл белгінің арасында ерлерге жылдамырақ жүру (рамаль) ұсынылады; нәзік жандылар қалыпты қадаммен жүреді. Умра сағиынан кейін шаш қысқарту (ерлерге қырыну да болады, ол — артықшылықты) немесе ұштарын кесу (нәзік жандыларға саусақ буынындай ұзындықта), содан кейін умра ихрамынан шығады (таматту‘ жасаушыларға).\n\nҒұрыптың негізі — Исмаил пайғамбардың (оған сәлем болсын) анасы Хажардың тарихы: Аллаһтың бұйрығымен суы жоқ алқапта қалдырылған ол, ұлы үшін су іздеп, Замзам бұлағы аяғының түбінен атқылағанша, екі төбенің арасын жеті рет жүгіріп өткен (хадис, Бухари 3364). Сағи — оның жолын сөзбе-сөз қайталау, талпыныс пен Аллаһқа тәуекел етудің бір-біріне қайшы келмейтінінің еске салуы.\n\nТәжірибе: сағи кезінде және одан кейін Замзам суын қанып ішіңіз — сүннет бойынша оны тұрып, Қағбаға қарап, өз ниетіңізбен дұға етіп ішеді.\n\nШарттары: ғалымдардың көпшілігі сағидың жарамды тауафтан кейін жасалуын талап етеді (сағиды тауафтан бұрын жасауға болмайды); ханбалилер олардың арасында аздаған кідірісті рұқсат етеді. Сағи үшін дәрет ұсынылады, бірақ тауафтан айырмашылығы, міндетті емес — дәретсіз де орындауға болады. Өз бетінше жүре алмайтындарға арнайы жолда мүгедектер арбасын немесе электрокарды пайдалану рұқсат етіледі; арбаны итеретін сүйемелдеуші, егер өзінде де ниет болса, сол уақытта өз сағиін де жасай алады.' },
      { t: '5. Арафат (9 Зуль-хиджа)', tKk: '5. Арафат (Зул-хижаның 9-ы)',
        d: 'Столп хаджа: «Хадж — это Арафа» (хадис, Тирмизи 889). Стояние (вукуф) — с полудня (после зухра) 9-го числа до заката. Желательно стоять у скалы (джабаль ар-Рахма), но действительно стояние в любой точке долины Арафат (кроме Урана — отдельной территории вне границ Арафата). Проводят время в дуа, зикре, истигфаре, читая проповедь (хутба) перед объединённым намазом зухр+аср, сокращённым и объединённым. Кто не смог достичь Арафата хотя бы на короткое время в указанный промежуток — по мнению большинства учёных хадж не засчитывается и переходит в умру, с необходимостью восполнить хадж позже.\n\nХадис (Тирмизи 3585, хасан): «Нет дня, в который Аллах освобождает от Огня больше рабов, чем день Арафа». В этот день Аллах гордится стоящими и говорит ангелам: «Что хотят эти [люди]?» (Муслим 1348) — само присутствие на Арафате уже приближает к прощению.\n\nПрактика: не тратить время стояния на разговоры или фотографии — большую часть дня посвящать дуа с поднятыми руками, лицом к кибле, и истигфару.\n\nГраницы долины Арафат чётко размечены указателями по всему периметру; палатка или машина паломника должны находиться внутри этих границ хотя бы часть времени вукуфа. Учёные разрешают засчитать стояние даже спящему, находящемуся без сознания или в дороге через долину, при условии присутствия его тела на территории Арафата в установленный промежуток. Дуа Пророка ﷺ, которое он чаще всего повторял в этот день: «Ля иляха илля-Ллаху вахдаху ля шарика лях, ляху-ль-мульку ва ляху-ль-хамду ва хува аля кулли шайин кадир» — считается лучшей формой поминания дня Арафа.',
        dKk: 'Хаждың тірегі: «Хадж — Арафа» (хадис, Тирмизи 889). Тұру (уқуф) — 9-ы күні түстен (зухрдан) кейін күн батқанға дейін. Рахмат тауының (жабал ар-Рахма) жанында тұру ұсынылады, бірақ Арафат алқабының кез келген нүктесінде тұру да жарамды (Уранадан басқа — Арафат шекарасынан тыс аумақ). Уақыт дұғада, зікірде, истиғфарда өтеді, қысқартылып біріктірілген зухр+аср намазынан бұрын уағыз (хутба) оқылады. Көрсетілген уақыт аралығында Арафатқа тіпті қысқа уақытқа болса да жете алмаған адамның хажы, көп ғалымның пікірінше, есептелмейді және умраға айналады, кейін хажды толтыру керек болады.\n\nХадис (Тирмизи 3585, хасан): «Аллаһ құлдарын Оттан ең көп босататын күн — Арафа күнінен артық күн жоқ». Осы күні Аллаһ тұрып жатқандарды мақтан тұтып, періштелерге: «Бұлар не қалайды?» дейді (Мүслім 1348) — Арафатта болудың өзі кешірімге жақындатады.\n\nТәжірибе: тұру уақытын әңгімеге немесе суретке түсуге жұмсамаңыз — күннің көп бөлігін қолды көтеріп, Қағбаға (қыбылаға) қарап дұға етуге және истиғфарға арнаңыз.\n\nАрафат алқабының шекаралары периметр бойынша белгілермен нақты сызылған; қажының шатыры немесе көлігі уқуф уақытының кем дегенде бір бөлігінде осы шекара ішінде болуы керек. Ғалымдар ұйықтап жатқан, есінен танған немесе алқап арқылы жол жүріп бара жатқан адамға да, тек денесі белгіленген уақыт аралығында Арафат аумағында болса, тұруды есептеуге рұқсат етеді. Пайғамбардың ﷺ осы күні жиі қайталаған дұғасы: «Ля иляha илля-Ллаху уахдаху ля шарика ляh, ляhу-ль-мульку уа ляhу-ль-хамду уа hуа аля кулли шайин Қадир» — Арафа күнінің ең жақсы еске алу түрі саналады.' },
      { t: '6. Муздалифа', tKk: '6. Муздалифа',
        d: 'После заката 9-го числа переезжают в Муздалифу: намазы магриб и иша объединяют и совершают вместе по прибытии (магриб не совершают отдельно по дороге), ночуют под открытым небом (масджид не обязателен), собирают 49 или 70 камешков размером с горошину/боб для побития джамаратов. После фаджра 10-го — короткое стояние и дуа у Машар аль-Харам, затем отправление в Мину до восхода солнца. Слабым, пожилым, женщинам и их сопровождающим по сунне разрешено выехать из Муздалифы раньше, во второй половине ночи, чтобы успеть в Мину до давки.\n\nХадис (Бухари 1672, Муслим 1218): Пророк ﷺ, прибыв в Муздалифу, совершил магриб и иша вместе без намазов между ними, а затем лёг спать до фаджра — сунна показывает, что ночь в Муздалифе не требует особых обрядов сверх намаза, сбора камней и отдыха.\n\nПрактика: собирать камешки размером с горошину, а не крупные — крупные камни считаются чрезмерностью (гулюв) в поклонении, порицаемой хадисом (Ибн Маджа 3029, хасан).\n\nНочёвка (мабит) в Муздалифе большинством учёных считается ваджибом (обязательным действием, а не столпом): пропуск без уважительной причины требует жертвы-искупления, но не делает хадж недействительным, в отличие от пропуска Арафата. Достаточным для выполнения ваджиба считается нахождение в границах Муздалифы хотя бы часть времени после полуночи, даже без сна. Камни для побития можно собрать заранее в любом чистом месте (не обязательно именно в Муздалифе) — некоторые учёные разрешают взять их даже в Мине.',
        dKk: '9-ы күні күн батқаннан кейін Муздалифаға көшеді: магриб пен иша намаздары жеткен соң бірге оқылады (магрибті жолда бөлек оқымайды), ашық аспан астында түнейді (мешіт міндетті емес), джамараттарға лақтыру үшін бұршақ мөлшеріндей 49 немесе 70 тас жинайды. 10-ы күні таңнан кейін Мәшғар әл-Харамда қысқаша тұрып дұға етеді, содан кейін күн шықпай тұрып Минаға аттанады. Әлсіздерге, қарттарға, нәзік жандыларға және олардың сүйемелдеушілеріне сүннет бойынша Муздалифадан ертерек, түннің екінші жартысында шығып, кептелістен бұрын Минаға жетуге рұқсат етіледі.\n\nХадис (Бухари 1672, Мүслім 1218): Пайғамбар ﷺ Муздалифаға жеткенде, магриб пен ишаны арасына басқа намаз кірмей бірге оқыды, содан кейін таңға дейін ұйықтады — бұл сүннет Муздалифа түнінде намаз, тас жинау және демалудан басқа арнайы ғұрып қажет еместігін көрсетеді.\n\nТәжірибе: бұршақ мөлшеріндей тас жинаңыз, ірі емес — ірі тастар ғибадатта шектен шығу (ғулюв) саналады, хадисте айыпталады (Ибн Мажа 3029, хасан).\n\nМуздалифада түнеу (мәбит) ғалымдардың көпшілігінің пікірінше уәжіп (тірек емес, міндетті әрекет): дәлелсіз себепсіз қалдырса, өтемдік құрбандық талап етіледі, бірақ Арафатты қалдырудан айырмашылығы, хажды жарамсыз етпейді. Уәжіпті орындау үшін түн жартысынан кейін Муздалифа шекарасында, ұйықтамаса да, кем дегенде біраз уақыт болу жеткілікті. Лақтыруға арналған тастарды алдын ала кез келген таза жерден жинауға болады (міндетті түрде Муздалифада емес) — кейбір ғалымдар оларды тіпті Минада алуға да рұқсат етеді.' },
      { t: '7. Побитие джамарата аль-Акаба (10 Зуль-хиджа)', tKk: '7. Джамарат әл-Ақабаға тас лақтыру (Зул-хижаның 10-ы)',
        d: 'В день праздника (Ид аль-Адха) сначала побивают только большой столб (джамарат аль-Акаба) семью камешками, произнося такбир на каждый бросок, без остановки для дуа. Время — от восхода солнца 10-го, лучшее — после восхода, но допустимо и позже, включая ночь. После этого — жертвоприношение, затем халяк/таксар. Порядок трёх действий (побитие → жертва → бритьё) желателен, но по хадису «делай — не будет греха» перестановка при незнании или забывчивости допустима.\n\nХадис (Муслим 1297): «Учитесь у меня обрядам хаджа» — сказано Пророком ﷺ именно у джамарата аль-Акаба, что стало основой принципа точного следования его действиям во всех обрядах хаджа.\n\nПрактика: при сильной давке разрешается перепоручить побитие камней доверенному лицу (для тех, кто физически не в состоянии — больным, беременным, пожилым), которое бросает сначала за себя, затем за подопечного.\n\nТехническое условие: каждый камешек должен попасть именно в столб или в чашу вокруг него — если камень упал мимо и не долетел, бросок не засчитывается и его нужно повторить. Такбир произносится с каждым броском, но, по мнению большинства, не является строгим условием действительности — забывший его хадж не портит. Современные многоуровневые платформы джамарата (после реконструкции) позволяют бросать с разных этажей — засчитывается любой уровень, лишь бы камень достиг цели.',
        dKk: 'Мейрам күні (Ид әл-Адха) алдымен тек үлкен бағанаға (джамарат әл-Ақаба) жеті тас лақтырады, әр лақтырғанда такбир айтады, дұғаға тоқтамай. Уақыты — 10-ы күні күн шыққаннан бастап, ең жақсысы — таң атқаннан кейін, бірақ түнге дейін де жарамды. Осыдан кейін — құрбандық, содан соң қырыну/қысқарту. Үш әрекеттің реті (тас лақтыру → құрбандық → қырыну) ұсынылады, бірақ «істей бер, күнә жоқ» хадисі бойынша білместіктен немесе ұмытып кетуден реттің ауысуы рұқсат етіледі.\n\nХадис (Мүслім 1297): «Хаждың ғұрыптарын менен үйреніңдер» — Пайғамбар ﷺ дәл осы сөзді джамарат әл-Ақабаның жанында айтқан, бұл оның хаждың барлық ғұрыптарындағы әрекеттеріне дәл еруі қағидасының негізі болды.\n\nТәжірибе: қатты кептеліс кезінде тас лақтыруды сенімді адамға (дене жағынан шамасы келмейтіндерге — науқастарға, жүкті әйелдерге, қарттарға) тапсыруға рұқсат етіледі, ол алдымен өзі үшін, содан кейін қамқорлығындағы адам үшін лақтырады.\n\nТехникалық шарт: әрбір тас дәл бағанаға немесе оның айналасындағы науаға тиуі керек — тас жетпей түсіп қалса, лақтыру есептелмейді және оны қайталау керек. Такбир әр лақтырумен бірге айтылады, бірақ көпшіліктің пікірінше, бұл жарамдылықтың қатаң шарты емес — ұмытып кеткен адамның хажы бұзылмайды. Қайта құрылымдалған заманауи көп қабатты джамарат платформалары әр түрлі қабаттан лақтыруға мүмкіндік береді — тас мақсатына жетсе, кез келген қабат есептеледі.' },
      { t: '8. Жертвоприношение (хади/удхийа)', tKk: '8. Құрбандық (хади/удхия)',
        d: 'Для совершающих хадж таматту‘ или кыран жертвоприношение обязательно (хади) — овца/коза целиком, или доля (1/7) в верблюде/корове. Ифрад — жертва не обязательна, но желательна. Мясо: часть можно съесть самому, часть подарить, часть раздать бедным; сейчас чаще оформляют через специальные купоны/фонды (например, при Исламском банке развития), чтобы забой и раздача прошли организованно. Кто не может позволить жертву — постится 3 дня в дни хаджа (лучше до Арафата или в дни ташрика) и 7 дней по возвращении домой — итого 10 полных дней (2:196).\n\nКоран (22:37): «Не дойдёт до Аллаха ни мясо, ни кровь их, а дойдёт до Него ваша богобоязненность» — смысл жертвоприношения не в самом акте, а в намерении и покорности, по примеру пророка Ибрахима (мир ему), готового принести в жертву сына (37:102–107).\n\nПрактика: оформлять жертвоприношение через надёжный официальный канал (Исламский банк развития и подобные структуры) и сохранить квитанцию — задержка в организованной раздаче не отменяет действительности жертвы, если оплата произведена в установленные дни.\n\nВременные рамки: классически жертву режут с утра 10-го до заката 13-го Зуль-хиджа (все четыре дня, включая дни ташрика); современные фетвы (в т.ч. решения фикх-академий) допускают завершение раздачи чуть позже при организованной системе через фонды, если оплата произведена вовремя. Разница между хади (обязательная жертва хаджа таматту‘/кыран) и удхией (добровольная жертва Курбан-байрама, не связанная с хаджем) в том, что хади можно совершать только в Мекке/Мине, а удхию — в любом месте проживания. Для доли в верблюде или корове (1/7) участники должны сойтись в общем намерении жертвы — не обязательно все ради хаджа, можно совместить хади одного человека с курбани других.',
        dKk: 'Таматту‘ немесе кыран хажын жасаушыларға құрбандық (хади) міндетті — тұтас қой/ешкі, немесе түйе/сиырдағы 1/7 үлес. Ифрадта құрбандық міндетті емес, бірақ ұсынылады. Ет: бір бөлігін өзі жеуге, бір бөлігін сыйлауға, бір бөлігін кедейлерге таратуға болады; қазір көбіне арнайы купон/қорлар арқылы (мысалы, Ислам даму банкі жанындағы) ұйымдастырылып сойылады және таратылады. Құрбандыққа шамасы келмеген адам хадж күндерінде (жақсысы Арафатқа дейін немесе ташрик күндерінде) 3 күн, үйге қайтқаннан кейін 7 күн ораза ұстайды — барлығы 10 толық күн (2:196 аяты).\n\nҚұран (22:37): «Олардың еті де, қаны да Аллаһқа жетпейді, тек тақуалықтарың Оған жетеді» — құрбандықтың мәні әрекеттің өзінде емес, ниет пен мойынсұнуда, ұлын құрбандыққа шалуға дайын болған Ибраһим пайғамбардың (оған сәлем болсын) үлгісінде (37:102–107 аяттары).\n\nТәжірибе: құрбандықты сенімді ресми арна арқылы (Ислам даму банкі және соған ұқсас құрылымдар) рәсімдеп, түбіртегін сақтаңыз — ұйымдастырылған таратудағы кідіріс, төлем белгіленген күндерде жасалса, құрбандықтың жарамдылығын жоймайды.\n\nУақыт шеңбері: классикалық түрде құрбандық 10-ы күнгі таңнан 13-і күнгі күн батқанға дейін (ташрик күндерін қоса, барлық төрт күн) сойылады; заманауи фетуалар (соның ішінде фикх академияларының шешімдері) төлем уақытылы жасалса, ұйымдастырылған қорлар арқылы таратудың сәл кешірек аяқталуына рұқсат етеді. Хади (таматту‘/кыран хажының міндетті құрбандығы) мен удхия (хажға байланысты емес, Құрбан айт мерекесінің ерікті құрбандығы) айырмашылығы — хади тек Меккеде/Минада, ал удхияны кез келген тұрғылықты жерде жасауға болады. Түйе немесе сиырдан 1/7 үлеске қатысушылар ортақ құрбандық ниетінде бірігуі керек — бәрі міндетті түрде хадж үшін болуы шарт емес, бір адамның хадиін басқалардың құрбанайттарымен біріктіруге болады.' },
      { t: '9. Дни ташрика и побитие трёх столбов (11–13)', tKk: '9. Ташрик күндері және үш бағанаға тас лақтыру (11–13)',
        d: 'В 11, 12 и 13-й дни Зуль-хиджа (дни ташрика) каждый день после зенита (после наступления времени зухра) побивают все три столба по порядку: малый (сугра), средний (вуста), большой (аль-Акаба) — по семь камешков на каждый, с дуа и поднятыми руками после малого и среднего (не после большого). Спешащий (мутааджиль) может покинуть Мину после побития 12-го числа, до заката, оставив камни 13-го дня; задержавшийся (мутааххир) остаётся до 13-го включительно — оба варианта равноценны по награде (2:203).\n\nХадис (Муслим 1141): «Дни ташрика — это дни еды, питья и поминания Аллаха» — в эти дни пост запрещён (кроме поста за не найденную жертву, 2:196), это дни праздничного гостеприимства и благодарности.\n\nПрактика: между побитием столбов уместно активно поминать Аллаха (такбир, тахмид) — сподвижники громко произносили такбир на рынках и в шатрах Мины все дни ташрика.\n\nВажный нюанс: пропущенные по ошибке или из-за давки броски одного дня можно восполнить на следующий день или даже позже в пределах дней ташрика, но не после заката 13-го числа — тогда требуется искупление жертвой. Порядок трёх столбов (малый → средний → большой) обязателен по сунне; изменение порядка требует повторения в правильной последовательности. Женщинам, детям и немощным разрешено, по мнению многих учёных, поручать побитие камней доверенному лицу и в дни ташрика на тех же основаниях, что и в день праздника.',
        dKk: 'Зул-хижаның 11, 12, 13-ы күндері (ташрик күндері) әр күні түстен кейін (зухр уақыты кіргеннен соң) үш бағананың бәрін ретімен лақтырады: кіші (сұғра), орта (уұста), үлкен (әл-Ақаба) — әрқайсысына жеті тас, кіші мен ортадан кейін қол көтеріп дұға етіледі (үлкеннен кейін жоқ). Асыққан (мутааджиль) 12-і күні лақтырғаннан кейін, күн батпай тұрып Минадан шығып, 13-і күнгі тасты қалдыра алады; кешіктірген (мутааххир) 13-іге дейін қалады — екі жол да сауап жағынан тең (2:203 аяты).\n\nХадис (Мүслім 1141): «Ташрик күндері — тамақ ішу, су ішу және Аллаһты еске алу күндері» — бұл күндері ораза тыйым салынған (табылмаған құрбандық үшін ұстайтын ораза, 2:196 аятынан басқа), бұл мейрамдық қонақжайлылық пен шүкірлік күндері.\n\nТәжірибе: бағаналарға тас лақтырудың арасында Аллаһты белсенді еске алу (такбир, тахмид) жарасады — сахабалар ташрик күндерінің бәрінде базарларда және Мина шатырларында такбирді дауыстап айтатын.\n\nМаңызды нюанс: кептеліс немесе қателік салдарынан бір күні өткізіп алынған лақтыруларды келесі күні немесе тіпті ташрик күндерінің шегінде кейінірек толтыруға болады, бірақ 13-і күнгі күн батқаннан кейін емес — сол кезде құрбандықпен өтеу талап етіледі. Үш бағананың реті (кіші → орта → үлкен) сүннет бойынша міндетті; ретті бұзу дұрыс кезекпен қайталауды талап етеді. Нәзік жандыларға, балаларға және әлсіздерге көптеген ғалымдардың пікірінше, ташрик күндерінде де мейрам күніндегідей негіздерде тас лақтыруды сенімді адамға тапсыруға рұқсат етіледі.' },
      { t: '10. Халяк / таксар (бритьё или укорачивание)', tKk: '10. Халяк / таксар (қырыну немесе қысқарту)',
        d: 'После жертвоприношения — полное бритьё головы (халяк, предпочтительнее для мужчин, за это отдельная дуа Пророка ﷺ трижды) или укорачивание волос по всей голове (таксар). Женщины только укорачивают — срезают кончик косы длиной с фалангу пальца, полное бритьё им не предписано. После этого действия наступает первое снятие ограничений ихрама (тахаллюль авваль) — дозволено всё, кроме близости с супругом(ой), до тавафа ифада.\n\nХадис (Бухари 1727, Муслим 1301): Пророк ﷺ трижды произнёс дуа за обривших голову и один раз — за укоротивших; на вопрос сподвижников он ответил после третьего раза: «И за укоротивших» — учёные толкуют это как указание на предпочтительность полного бритья для мужчин, без принижения укорачивания как действительной альтернативы.\n\nПрактика: женщинам следует именно подрезать кончики волос, а не бриться полностью — это в исламе им не предписано.\n\nМужчине, совершившему умру (не хадж), также предписано бритьё или укорачивание волос сразу после са‘и, до выхода из ихрама умры — это отдельное, самостоятельное действие, не совпадающее с бритьём после хаджа. Если у мужчины нет волос на голове (лысина), символическое проведение бритвой по коже засчитывается как выполнение обряда. Некоторые современные учёные (в частности, отдельные фетвы Постоянного комитета) допускают для женщин, оказавшихся в местах с высокой скученностью, укорачивание прядей у любого доступного участка головы, если добраться до кончика косы физически невозможно.',
        dKk: 'Құрбандықтан кейін — басты толық қырыну (халяк, ерлерге артықшылықты, бұл үшін Пайғамбардың ﷺ үш рет ерекше дұғасы бар) немесе шаштың барлық жерінен қысқарту (тақсар). Нәзік жандылар тек қысқартады — өрімнің ұшынан саусақ буынындай кесіп алады, толық қырыну оларға бұйырылмаған. Осы әрекеттен кейін ихрамның бірінші шектеуден босауы (тахаллюль-и әууал) басталады — жұбайымен жақындықтан басқасының бәріне рұқсат, тауаф ифадаға дейін.\n\nХадис (Бухари 1727, Мүслім 1301): Пайғамбар ﷺ шашын қырғандар үшін үш рет, қысқартқандар үшін бір рет дұға етті; сахабалардың сұрағына үшінші реттен кейін: «Қысқартқандарға да» деп жауап берді — ғалымдар мұны ерлерге толық қырынудың артықшылығын көрсету деп түсіндіреді, қысқартуды жарамды балама ретінде кемсітпей.\n\nТәжірибе: нәзік жандыларға тек шаш ұштарын кесу керек, толық қырыну емес — бұл исламда оларға бұйырылмаған.\n\nУмра жасаған (хадж емес) ерге де сағиден кейін, умра ихрамынан шыққанға дейін, дереу қырыну немесе шашын қысқарту бұйырылған — бұл хаждан кейінгі қырынумен сәйкес келмейтін, бөлек, дербес әрекет. Ердің басында шашы болмаса (тақыр бас), ұстараны терісінен өткізудің символикалық түрде жасалуы ғұрыпты орындау болып есептеледі. Кейбір заманауи ғалымдар (атап айтқанда, Тұрақты комитеттің жекелеген фетуалары) қатты кептеліс орындарында қалған нәзік жандыларға, өрімнің ұшына жету дене жағынан мүмкін болмаса, басының кез келген қолжетімді жерінен шаш қысқартуға рұқсат етеді.' },
      { t: '11. Таваф ифада (столп хаджа)', tKk: '11. Тауаф ифада (хаждың тірегі)',
        d: 'Обязательный таваф хаджа, совершается после Арафата — обычно в день Ид аль-Адха (10-го) или в один из дней ташрика, время не ограничено строго. За тавафом ифада следует са‘и, если он не был совершён ранее (для хаджи ифрад/кыран, не делавших умру заранее, — обязательно; для таматту‘ — уже сделан при умре, повторять не нужно). После тавафа ифада и завершения всех действий тахаллюля наступает второе снятие ограничений (тахаллюль сани) — разрешено абсолютно всё, включая близость с супругом(ой).\n\nКоран (22:29): «Пусть они завершат свои обряды, исполнят свои обеты и обойдут вокруг древнего Дома» — на этот аят опираются учёные, называя таваф ифада столпом хаджа наравне со стоянием на Арафате: без него хадж считается незавершённым.\n\nПрактика: сильно уставшим или больным допустимо отложить таваф ифада на несколько дней после дней Мины — срок не ограничен строго, в отличие от Арафата, но затягивать без причины не рекомендуется.\n\nЕсли женщина не может совершить таваф ифада из-за месячных до отъезда группы, а очищение не наступает, современные учёные допускают приём средств для задержки менструации заранее (по совету врача) либо, при крайней необходимости, следование мнению отдельных учёных (например, Ибн Таймии) о допустимости тавафа при непрекращающемся кровотечении в случае крайней нужды — вопрос требует консультации со знающим человеком на месте. До совершения тавафа ифада паломник остаётся в первом тахаллюле — сбрившийся, но не завершивший все столпы хаджа.',
        dKk: 'Хаждың парыз тауафы, Арафаттан кейін жасалады — әдетте Ид әл-Адха күні (10-ы) немесе ташрик күндерінің бірінде, уақыты қатаң шектелмейді. Тауаф ифададан кейін, бұрын жасалмаса, сағи жасалады (алдын ала умра жасамаған ифрад/кыран хажылары үшін — міндетті; таматту‘ хажылары үшін умрада жасалған, қайталау керек емес). Тауаф ифада мен барлық тахаллюль әрекеттері аяқталғаннан кейін екінші шектеуден босау (тахаллюль-и сани) басталады — жұбайымен жақындықты қоса, мүлдем бәріне рұқсат.\n\nҚұран (22:29): «Олар өз ғұрыптарын аяқтасын, өз ниеттерін орындасын және ежелгі Үйді тауаф етсін» — ғалымдар осы аятқа сүйеніп, тауаф ифаданы Арафатта тұрумен қатар хаждың тірегі деп атайды: онсыз хадж аяқталмаған саналады.\n\nТәжірибе: қатты шаршаған немесе науқас адамдарға тауаф ифаданы Мина күндерінен кейін бірнеше күнге қалдыруға болады — Арафаттан айырмашылығы, мерзімі қатаң шектелмейді, бірақ себепсіз созуға болмайды.\n\nТобы кетер алдында хайыз себебінен тауаф ифаданы жасай алмаған, ал тазару да болмаған нәзік жанды үшін заманауи ғалымдар дәрігердің кеңесімен етеккірді алдын ала кідірту дәрілерін қабылдауға немесе, аса қажет болған жағдайда, кейбір ғалымдардың (мысалы, Ибн Теймийенің) пікірін ұстануға — тоқтамайтын қан кету жағдайында аса қажеттілік туғанда тауафтың рұқсат етілуі туралы — рұқсат етеді; бұл мәселе жергілікті жерде білетін адаммен кеңесуді талап етеді. Тауаф ифада жасалғанға дейін қажы бірінші тахаллюльде қалады — қырынған, бірақ хаждың барлық тіректерін аяқтамаған күйде.' },
      { t: '12. Таваф прощания (вада‘)', tKk: '12. Қоштасу тауафы (уада‘)',
        d: 'Последний обход Каабы непосредственно перед выездом из Мекки, без последующего задерживания в городе без нужды (по хадису — уходить сразу после него). Обязателен для большинства паломников; женщины в состоянии хайда или нифаса освобождены от него по облегчению (без фидьи), но по некоторым мнениям желательно постоять у выхода из Заповедной мечети и сделать дуа. Действия после: сборы и отъезд, желательно посетить мечеть Пророка ﷺ в Медине (не столп хаджа, отдельная сунна).\n\nХадис (Муслим 1327): «Пусть никто не уезжает [из Мекки], пока последним его делом не станет [таваф вокруг] Дома» — Пророк ﷺ прямо указал, что этот обход должен быть последним действием паломника в Мекке.\n\nПрактика: не совершать покупки или длительные прощания после этого тавафа — по сунне паломник направляется прямо к выходу и в путь, сохраняя духовную сосредоточенность до самого отъезда.\n\nЖенщинам, у которых менструация началась уже после выполнения всех столпов хаджа, но перед самым отъездом, таваф прощания прощается без всякого искупления — это единственный обряд хаджа, полностью снимаемый по уважительной причине без фидьи. Задержавшимся в Мекке после тавафа вада‘ на короткое время по объективным причинам (сборы багажа, ожидание транспорта) таваф повторять не нужно — порицается лишь умышленное затягивание с делами, не связанными с необходимостью выезда.',
        dKk: 'Меккеден шығар алдында Қағбаны соңғы рет айналу, содан кейін қалада қажетсіз кідірмей (хадис бойынша — дереу жолға шығу). Көпшілік қажылар үшін міндетті; хайыз немесе нифас күйіндегі нәзік жандылар жеңілдікпен одан босатылады (фидиясыз), бірақ кейбір пікірлер бойынша Харам мешітінің шығар есігінде тұрып дұға ету ұсынылады. Одан кейінгі әрекеттер: жиналу мен аттану, Мәдинадағы Пайғамбар ﷺ мешітін зиярат ету ұсынылады (хаждың тірегі емес, бөлек сүннет).\n\nХадис (Мүслім 1327): «Ешкім [Меккеден] оның соңғы ісі Үйді [тауаф ету] болмайынша кетпесін» — Пайғамбар ﷺ бұл айналымның қажының Меккедегі соңғы әрекеті болуы керектігін тікелей көрсеткен.\n\nТәжірибе: осы тауафтан кейін сауда жасамаңыз немесе ұзақ қоштасулар жасамаңыз — сүннет бойынша қажы аттанарда тікелей шығуға беттейді, аттанғанға дейін рухани шоғырлануын сақтайды.\n\nХаждың барлық тіректерін орындап болғаннан кейін, тек аттанар алдында ғана хайызы басталған нәзік жандыларға қоштасу тауафы ешбір өтемсіз кешіріледі — бұл хаждың себепті түрде фидиясыз толықтай алынып тасталатын жалғыз ғұрпы. Уада‘ тауафынан кейін Меккеде объективті себептермен (жүк жинау, көлікті күту) қысқа уақытқа қалғандарға тауафты қайталаудың қажеті жоқ — қажеттіліксіз әдейі істерді созу ғана мақрух саналады.' }
    ];

    const HAJJ_UMRAH_EXTRA = [
      { t: 'Умра отдельно (вне хаджа)', tKk: 'Бөлек умра (хаждан тыс)',
        d: 'Порядок: ихрам с миката (намерение + тальбия) → таваф Каабы (7 кругов) → два ракаата → са‘и (7 отрезков Сафа-Марва) → халяк/таксар → выход из ихрама. Можно совершать в любое время года, сколько угодно раз, но между двумя умрами желателен перерыв (не «конвейером» ради количества). Умра из Мекки (например, для местных жителей) требует выезда за пределы Харама до ближайшего дозволенного места (например, Тан‘им) для входа в ихрам. Умра в месяц Рамадан по награде сравнима с совершением хаджа вместе с Пророком ﷺ (хадис, Бухари 1863), но юридически не заменяет обязательный хадж и не освобождает от него.\n\nХадис (Бухари 1773, Муслим 1349): «Умра за умрой — искупление того, что между ними, а хадж, принятый [Аллахом], не имеет иной награды, кроме Рая» — умра служит своего рода духовным обновлением между большими паломничествами.\n\nПрактика: жителям Мекки, желающим умру, проще всего доехать до мечети Аиши в Тан‘име — ближайшей точки микатной границы, указанной Пророком ﷺ именно для таких случаев (Бухари 1784, Муслим 1211).\n\nПо мнению большинства учёных, между двумя умрами не установлено строгого минимального интервала, но ханбалитский мазхаб и ряд современных муфтиев советуют выдерживать хотя бы срок, достаточный для отрастания волос (около месяца), чтобы избежать формального «конвейера» ради количества, порицаемого духом обряда, а не буквой закона. Для тех, кто выезжает из Мекки по делам (например, в Джидду) и возвращается, при желании совершить ещё одну умру достаточно надеть ихрам с ближайшей границы Харама, а не обязательно снова ехать в Тан‘им, если их путь пролегает через другую точку миката.',
        dKk: 'Реті: миката ихрам кию (ниет + тәлбия) → Қағбаны тауаф ету (7 айналым) → екі рәкат намаз → сағи (Сафа-Марваның 7 аралығы) → қырыну/қысқарту → ихрамнан шығу. Жыл мезгіліне қарамай, қаншама рет жасауға болады, бірақ екі умраның арасында үзіліс болғаны жөн («конвейер» сияқты сан үшін жасамау). Меккеден (мысалы, жергілікті тұрғындарға) умра жасау үшін ихрам кию үшін Харам шекарасынан тыс жақын жерге (мысалы, Тәннимге) шығу керек. Рамазан айындағы умраның сауабы Пайғамбармен ﷺ бірге жасалған хажға теңеледі (хадис, Бухари 1863), бірақ бұл заңды түрде парыз хаждың орнын баспайды және одан босатпайды.\n\nХадис (Бухари 1773, Мүслім 1349): «Умрадан кейінгі умра — екеуінің арасындағыны өтейді, ал [Аллаһ] қабыл еткен хаждың сауабы Жәннаттан басқа ештеңе емес» — умра үлкен қажылықтардың арасындағы бір түрлі рухани жаңару қызметін атқарады.\n\nТәжірибе: умра жасағысы келетін Мекке тұрғындарына ең оңайы — Тәннимдегі Аиша мешітіне бару, бұл дәл осындай жағдайлар үшін Пайғамбар ﷺ көрсеткен ең жақын микат шекарасының нүктесі (Бухари 1784, Мүслім 1211).\n\nҒалымдардың көпшілігінің пікірінше, екі умра арасында қатаң ең аз аралық белгіленбеген, бірақ ханбали мазхабы мен бірқатар заманауи муфтилер, сан үшін «конвейер» жасамау үшін, кем дегенде шаш өсуге жеткілікті мерзімді (шамамен бір ай) күтуге кеңес береді — бұл шариғаттың әрпіне емес, ғұрыптың рухына қайшы келеді. Меккеден іс бойынша (мысалы, Джиддаға) шығып, қайта оралатын және тағы бір умра жасағысы келетіндерге, жолдары басқа микат нүктесі арқылы өтсе, міндетті түрде қайта Тәннимге бармай-ақ, Харамның ең жақын шекарасынан ихрам киюі жеткілікті.' },
      { t: 'Ошибки, фидья и что делать при нарушении', tKk: 'Қателер, фидия және бұзылған жағдайда не істеу керек',
        d: 'При случайном или вынужденном нарушении запрета ихрама (например, из-за болезни пришлось надеть обычную одежду или сбрить волосы) действует облегчение (2:196): «фидья одного вида» — пост 3 дня, или накормить 6 бедных, или заколоть овцу, на выбор паломника. При умышленном нарушении без причины — та же фидья, плюс тауба. Пропуск столпа (Арафат, таваф ифада, ихрам) делает хадж недействительным или требует восполнения в другой год; пропуск обязательного действия (ваджиб — например, ночёвка в Мине) восполняется жертвой. Совет: перед поездкой пройти краткие курсы у надёжной группы или имама, взять с собой памятку по своему мазхабу.\n\nОснование самого облегчения — формулировка Корана (2:196): «А если кто из вас болен или страдает недугом головы [и вынужден обрить её], то [пусть] совершит искупление постом, или милостыней, или жертвоприношением» — контекст аята прямо связан с вынужденным нарушением по болезни, а учёные распространили этот принцип и на другие подобные случаи.\n\nПрактика: если нарушение уже произошло, не пытаться скрыть его — открыто спросить сопровождающего учёного или официальную службу фетв (доступна и по телефону в сезон хаджа), какая именно фидья требуется.\n\nПорядок фидьи «одного вида» (2:196) построен по принципу свободного выбора паломника, а не по тяжести нарушения — пост 3 дня, кормление 6 бедных (по пол-са‘ пищи на каждого) или заклание овцы равноценны перед шариатом при непреднамеренном нарушении. Отдельная, более строгая категория — компенсация при умышленной охоте в состоянии ихрама (5:95) или намеренном повреждении растительности Харама — там она соразмерна причинённому ущербу, а не фиксирована. При любых сомнениях в правильности действий безопаснее сразу обратиться к сопровождающему алиму, чем полагаться на форумы или неофициальные источники в интернете.',
        dKk: 'Ихрам тыйымын байқаусызда немесе мәжбүрлікпен бұзғанда (мысалы, ауру салдарынан әдеттегі киім кисе немесе шашын алдырса) жеңілдік қолданылады (2:196): бір түрлі фидия — қажының өз таңдауы бойынша 3 күн ораза, немесе 6 кедейді тамақтандыру, немесе қой сою. Себепсіз әдейі бұзғанда — сол фидия, оған қоса тәубе. Тіректі қалдырып кету (Арафат, тауаф ифада, ихрам) хажды жарамсыз етеді немесе басқа жылы толтыруды талап етеді; уәжіб әрекетті қалдыру (мысалы, Минада түнеу) құрбандықпен толтырылады. Кеңес: сапар алдында сенімді топ немесе имамнан қысқа сабақ алу, өз мазһабы бойынша жадынама алып жүру.\n\nОсы жеңілдіктің негізі — Құранның (2:196) тұжырымы: «Ал сендердің біреуің науқас болса немесе бас ауруынан зардап шексе [және оны қырындыруға мәжбүр болса], онда ораза, садақа немесе құрбандық арқылы өтесін» — аяттың мәнмәтіні тікелей аурудан мәжбүр болған бұзушылықпен байланысты, ал ғалымдар бұл қағиданы ұқсас басқа жағдайларға да таратқан.\n\nТәжірибе: бұзушылық болып қойса, оны жасыруға тырыспаңыз — қандай нақты фидия керек екенін сүйемелдеуші ғалымнан немесе ресми фетуа қызметінен (хадж маусымында телефон арқылы да қолжетімді) ашық сұраңыз.\n\n«Бір түрлі» фидия (2:196 аяты) қажының еркін таңдау қағидасы бойынша құрылған, бұзушылықтың ауырлығына қарай емес — мақсатсыз бұзушылықта 3 күн ораза, 6 кедейді тамақтандыру (әрқайсысына жарты са‘ тағам) немесе қой сою шариғат алдында тең дәрежеде. Ихрам күйінде әдейі аң аулау (5:95 аяты) немесе Харам өсімдігін әдейі жою кезінде қолданылатын неғұрлым қатаң, жеке санат — келтірілген зиянға сай, тұрақты болмайтын өтем. Әрекеттің дұрыстығына күмән туындаған кез келген жағдайда форумдарға немесе бейресми интернет көздеріне сенгеннен гөрі, тікелей сүйемелдеуші алимге жүгінген қауіпсіз.' }
    ];

    const HAJJ_TYPES = [
      { title: 'Ифрад (إفراد)', titleKk: 'Ифрад (إفراد)',
        detail: 'Намерение только на хадж, без отдельной умры в этой же поездке. Жертвоприношение (хади) не обязательно, только по желанию. Обычно выбирают жители Мекки и её окрестностей или те, кто уже совершил умру отдельно ранее в этом году.\n\nАиша (р.а.) передаёт (Бухари 1562, Муслим 1211), что в прощальном хадже сподвижники разделились на три группы — ифрад, кыран и таматту‘ — и Пророк ﷺ одобрил все три варианта, не отдав явного предпочтения ни одному как обязательному для всех.\n\nПрактика: ифрад избавляет от обязательного хади при отсутствии необходимости выходить из ихрама между обрядами, что удобно тем, кто уже совершил умру в этом сезоне отдельно.\n\nШафииты и маликиты считают ифрад лучшим видом хаджа, ссылаясь на ряд версий хадиса о хадже Пророка ﷺ, где сообщается, что он совершил именно ифрад (Муслим 1211) — при этом другие достоверные риваяты того же хадиса называют кыран, что породило известное разногласие среди ранних имамов о точном виде хаджа самого Пророка ﷺ. Жителям Мекки и территории внутри границ миката вид таматту‘ в принципе недоступен согласно оговорке Корана «это для тех, чья семья не присутствует у Заповедной мечети» (2:196) — им остаются только ифрад или кыран, причём хади при этом с них не спрашивается.',
        detailKk: 'Осы сапарда бөлек умра жасамай, тек хаждға ниет ету. Құрбандық (хади) міндетті емес, тек өз еркімен. Әдетте Мекке және оның маңы тұрғындары немесе осы жылы бұрын бөлек умра жасағандар таңдайды.\n\nАиша (р.а.) риуаят етеді (Бухари 1562, Мүслім 1211), қоштасу хажында сахабалар үш топқа бөлінген — ифрад, кыран және таматту‘ — және Пайғамбар ﷺ үшеуін де мақұлдап, ешқайсысын бәріне міндетті деп ерекше артық санамаған.\n\nТәжірибе: ифрад ғұрыптардың арасында ихрамнан шығу қажеттілігі болмаған кезде міндетті хадиден босатады, бұл осы маусымда бөлек умра жасап үлгерген адамдарға ыңғайлы.\n\nШафии мен малики мазхабтары ифрадты хаждың ең жақсы түрі деп санайды, Пайғамбардың ﷺ хажы туралы кейбір хадис нұсқаларына сүйеніп, онда оның дәл ифрад жасағаны айтылады (Мүслім 1211) — сонымен қатар осы хадистің басқа сенімді риуаяттарында кыран аталады, бұл ерте имамдар арасында Пайғамбардың ﷺ хажының нақты түрі туралы белгілі келіспеушілікті тудырды. Мекке тұрғындары мен микат шекарасы ішіндегі аумақ тұрғындарына таматту‘ түрі принципті түрде қолжетімсіз, себебі Құрандағы «бұл — отбасы Харам мешітінің жанында тұрмайтындар үшін» (2:196) деген ескертпе бойынша — оларға тек ифрад немесе кыран қалады, әрі хади олардан талап етілмейді.' },
      { title: 'Таматту‘ (تمتع)', titleKk: 'Таматту‘ (تمتع)',
        detail: 'Сначала совершают умру в месяцы хаджа (с Шавваля по 10 Зуль-хиджа), выходят из ихрама, живут обычной жизнью, затем в день Тарвия (8 Зуль-хиджа) берут новый ихрам для хаджа прямо из Мекки. Требуется обязательное жертвоприношение (хади таматту‘); при невозможности — 3 дня поста в хадже и 7 по возвращении (2:196). Самый распространённый вид среди паломников издалека.\n\nКоран (2:196) прямо называет этот вид: «А кто пользуется умрой до хаджа, тот обязан принести в жертву то, что окажется доступным». По хадису (Бухари 1568), большинство сподвижников в прощальном хадже перешли именно на таматту‘ по указанию Пророка ﷺ, выйдя из ихрама после умры и войдя в новый ихрам для хаджа позже.\n\nПрактика: между умрой и новым ихрамом для хаджа паломник живёт как обычный человек — может пользоваться парфюмом и стричь волосы, все ограничения ихрама временно сняты.\n\nХанбалитский мазхаб считает таматту‘ лучшим видом хаджа, поскольку он сочетает оба обряда с наименьшим временем пребывания в ограничениях ихрама и, по мнению этого мазхаба, ближе всего к прямому указанию Пророка ﷺ его сподвижникам перейти именно на этот вид в прощальном хадже. Паломнику, выбравшему таматту‘, между умрой и хаджем не обязательно оставаться бездеятельным — можно, но не обязательно, совершить ещё одну добровольную умру, хотя большинство учёных советуют просто отдохнуть и подготовиться к хаджу, не гонясь за количеством умр.',
        detailKk: 'Алдымен хадж айларында (Шәууәлден Зул-хижаның 10-на дейін) умра жасайды, ихрамнан шығады, әдеттегідей өмір сүреді, содан кейін Тарвия күні (8 Зул-хижа) Меккеден хаждға жаңа ихрам киеді. Құрбандық (хади таматту‘) міндетті; мүмкін болмаса — хажда 3 күн, қайтқанда 7 күн ораза (2:196 аяты). Алыстан келетін қажылар арасында ең көп тараған түрі.\n\nҚұран (2:196) осы түрді тікелей атайды: «Кім хаждан бұрын умрамен пайдаланса, оған табылған нәрседен құрбандық шалу міндетті». Хадис бойынша (Бухари 1568), қоштасу хажында сахабалардың көпшілігі Пайғамбардың ﷺ нұсқауымен дәл таматту‘ға көшкен, умрадан кейін ихрамнан шығып, кейінірек хаждға жаңа ихрам киген.\n\nТәжірибе: умра мен хаджға жаңа ихрам кию арасында қажы қарапайым адамдай өмір сүреді — хош иіс жағуға, шашын қиюға болады, ихрамның барлық шектеулері уақытша алынады.\n\nХанбали мазхабы таматту‘ты хаждың ең жақсы түрі деп санайды, себебі ол екі ғұрыпты да ихрам шектеуінде ең аз уақыт болумен біріктіреді және, осы мазхаб бойынша, Пайғамбардың ﷺ қоштасу хажында сахабаларына дәл осы түрге көшуді тікелей нұсқауына жақын. Таматту‘ды таңдаған қажы умра мен хаждың арасында әрекетсіз қалуға міндетті емес — қаласа, тағы бір ерікті умра жасауға болады, дегенмен ғалымдардың көпшілігі сан үшін қумай, жай демалып, хаджға дайындалуды кеңес береді.' },
      { title: 'Кыран (قران)', titleKk: 'Кыран (قران)',
        detail: 'Единый ихрам сразу на умру и хадж (намерение на оба обряда вместе или добавление намерения хаджа к умре до начала тавафа). Ихрам не снимается до тавафа ифада — паломник дольше остаётся в ограничениях ихрама. Как и таматту‘, требует обязательного жертвоприношения.\n\nОснование — тот же хадис о прощальном хадже, где часть сподвижников вошла в ихрам сразу с намерением и умры, и хаджа вместе (по вопросу о виде хаджа самого Пророка ﷺ мнения мазхабов расходятся).\n\nПрактика: кыран освобождает от необходимости заново облачаться в ихрам между умрой и хаджем, но требует более долгого пребывания в его ограничениях — стоит заранее оценить, хватит ли выносливости на весь этот срок.\n\nХанафитский мазхаб считает кыран лучшим видом хаджа среди трёх, поскольку он объединяет достоинства обоих обрядов в одном непрерывном ихраме и, по мнению этого мазхаба, ближе всего к практике самого Пророка ﷺ, чей хадж, по ряду достоверных риваятов (Бухари 1785, Муслим 1211), был именно кыраном. При кыране паломник совершает только один таваф и одно са‘и на оба обряда сразу — по мнению большинства, кроме шафиитов, которые требуют раздельный таваф и са‘и для умры и хаджа даже при едином ихраме.',
        detailKk: 'Умра мен хаджға бірден бір ихраммен ниет ету (екеуіне қатар ниет ету немесе тауаф басталғанға дейін умраға хадждың ниетін қосу). Тауаф ифадаға дейін ихрамнан шықпайды — қажы ихрам шектеуінде ұзағырақ қалады. Таматту‘ сияқты міндетті құрбандықты талап етеді.\n\nНегізі — қоштасу хажы туралы сол хадис, онда сахабалардың бір бөлігі бірден умра мен хаждың ниетімен ихрамға кірген (Пайғамбардың ﷺ өз хажының түрі туралы мазһабтардың пікірлері әртүрлі).\n\nТәжірибе: кыран умра мен хадждың арасында ихрамды қайта кию қажеттілігінен босатады, бірақ оның шектеулерінде ұзағырақ болуды талап етеді — осы бүкіл мерзімге шыдамдылық жетер ме, алдын ала бағалаған жөн.\n\nХанафи мазхабы кыранды үш түрдің ішіндегі ең жақсысы деп санайды, себебі ол екі ғұрыптың артықшылығын бір үздіксіз ихрамда біріктіреді және, осы мазхаб бойынша, Пайғамбардың ﷺ өз тәжірибесіне ең жақыны, оның хажы бірқатар сенімді риуаяттар бойынша (Бухари 1785, Мүслім 1211) дәл кыран болған. Кыранда қажы екі ғұрыпқа бірден тек бір тауаф пен бір сағи жасайды — көпшіліктің пікірінше, тек шафиилерден басқа, олар бір ихрамда болса да умра мен хаждың тауафы мен сағиін бөлек талап етеді.' },
      { title: 'Хадж и умра — в чём разница', titleKk: 'Хадж пен умра — айырмашылығы',
        detail: 'Хадж — пятый столп ислама, обязателен раз в жизни при наличии способности (истита‘а), совершается только в строго определённые дни (8–13 Зуль-хиджа) и включает Арафат, Муздалифу и Мину. Умра — желательный обряд (сунна муаккада по мнению многих учёных), состоит только из тавафа и са‘и, совершается в любое время года и занимает несколько часов. Хадж без умры возможен (ифрад); умра без хаджа — обычная практика, но не заменяет обязательный хадж.\n\nХадис (Тирмизи 889): «Хадж — это Арафа» — эта фраза показывает, что именно стояние на Арафате отличает хадж от умры содержательно, поскольку умра вообще не включает выезд за пределы харама на Арафат.\n\nПрактика: при нехватке времени или средств полноценная умра доступна в любое время года, но она ни в коем случае не отменяет обязанность совершить хадж хотя бы раз в жизни при появлении возможности (истита‘а).\n\nНа практике умра занимает от нескольких часов до одного дня и не требует визы хаджа или квоты (в большинстве стран доступна по обычной умра-визе в любое время, кроме нескольких недель непосредственно перед хаджем), тогда как хадж требует официальной квоты, регистрации через духовное управление и пребывания в Мекке, Мине и Арафате не менее пяти-шести дней подряд.',
        detailKk: 'Хадж — исламның бесінші тірегі, мүмкіндік (істиғаат) болса, өмірде бір рет парыз, тек белгіленген күндерде (8–13 Зул-хижа) жасалады және Арафат, Муздалифа, Мина ғибадаттарын қамтиды. Умра — ұсынылған ғибадат (көп ғалым бойынша сүннат-и муаккада), тек тауаф пен сағидан тұрады, жыл мезгіліне қарамай жасалады және бірнеше сағатқа созылады. Умрасыз хадж (ифрад) мүмкін; хаджсыз умра — қалыпты тәжірибе, бірақ парыз хаждың орнын баспайды.\n\nХадис (Тирмизи 889): «Хадж — бұл Арафа» — бұл сөз тіркесі дәл Арафатта тұру хаджды умрадан мазмұны жағынан ерекшелендіретінін көрсетеді, себебі умра харам шекарасынан тыс Арафатқа шығуды мүлде қамтымайды.\n\nТәжірибе: уақыт немесе қаражат жетіспегенде толыққанды умра жыл мезгіліне қарамай қолжетімді, бірақ бұл мүмкіндік (істиғаат) туғанда өмірде кемінде бір рет хадж жасау парызын ешқашан алмастырмайды.\n\nІс жүзінде умра бірнеше сағаттан бір күнге дейін уақыт алады және хадж визасын немесе квотаны талап етпейді (көп елде хаждан бірнеше апта бұрынғы кезеңнен басқа, әдеттегі умра-визасымен жыл мезгіліне қарамай қолжетімді), ал хадж ресми квотаны, діни басқарма арқылы тіркелуді және Мекке, Мина мен Арафатта кемінде бес-алты күн қатарынан болуды талап етеді.' },
      { title: 'Какой вид хаджа выбрать на практике', titleKk: 'Іс жүзінде хаждың қай түрін таңдау керек',
        detail: 'Большинство паломников, приезжающих в организованных группах издалека, выбирают таматту‘ — он проще логистически (можно снять ихрам между умрой и хаджем, отдохнуть, переодеться) и наиболее распространён среди современных турагентств и духовных управлений. Кыран подходит тем, кто хочет объединить оба обряда в одном ихраме и готов физически и морально дольше находиться в его ограничениях — например, паломникам с ограниченным временем пребывания, которым неудобно дважды входить в состояние ихрама. Ифрад — вариант для жителей Мекки и её окрестностей (для которых таматту‘ шариатски недоступен), а также для тех, кто уже совершил отдельную умру ранее в этом году и не хочет платить за обязательную жертву.\n\nРазногласие имамов о предпочтительном виде восходит к разным пониманиям действий самого Пророка ﷺ в прощальном хадже: имамы аш-Шафии и Малик считали лучшим ифрад, Абу Ханифа — кыран, Ахмад ибн Ханбаль — таматту‘. Учёные единодушны, что все три вида действительны и допустимы для любого паломника (кроме местных жителей и таматту‘), а выбор между ними — вопрос удобства и следования избранному мазхабу, а не строгой обязательности одного варианта.\n\nПрактика: перед поездкой стоит уточнить, какой вид рекомендует турагентство или духовное управление вашей страны — обычно группы едут одним видом ради единого расписания, и самостоятельно менять его в последний момент неудобно логистически.',
        detailKk: 'Ұйымдастырылған топтармен алыстан келетін қажылардың көпшілігі таматту‘ды таңдайды — ол логистика жағынан оңайырақ (умра мен хаждың арасында ихрамнан шығып, демалып, киім ауыстыруға болады) және қазіргі турагенттіктер мен діни басқармалар арасында ең көп таралған. Кыран екі ғұрыпты бір ихрамда біріктіргісі келетін және оның шектеуінде ұзағырақ болуға дене мен рухани жағынан дайын адамдарға жарасады — мысалы, болу мерзімі шектеулі, ихрамға екі рет кіру ыңғайсыз қажыларға. Ифрад — Мекке және оның маңы тұрғындарына арналған нұсқа (оларға таматту‘ шариғи түрде қолжетімсіз), сондай-ақ осы жылы бұрын бөлек умра жасаған және міндетті құрбандық үшін төлегісі келмейтіндерге.\n\nИмамдардың артықшылықты түрі туралы келіспеушілігі Пайғамбардың ﷺ қоштасу хажындағы әрекеттерін әртүрлі түсінуден бастау алады: имам аш-Шафии мен Малик ифрадты ең жақсысы деп санады, Әбу Ханифа — кыранды, Ахмад ибн Ханбал — таматту‘ды. Ғалымдар үшеуінің де кез келген қажы үшін жарамды және рұқсат етілгеніне (жергілікті тұрғындар мен таматту‘дан басқа) бірауызды, ал олардың арасында таңдау — ыңғайлылық және таңдаған мазхабты ұстану мәселесі, бір нұсқаның қатаң міндеттілігі емес.\n\nТәжірибе: сапарға дейін турагенттік немесе еліңіздің діни басқармасы қай түрді ұсынатынын нақтылаған жөн — әдетте топтар бірыңғай кестеге ыңғайлы бір түрмен жүреді, соңғы сәтте оны өз бетінше өзгерту логистика жағынан ыңғайсыз.' },
      { title: 'Повторный хадж (нафль)', titleKk: 'Қайталама хадж (нәпіл)',
        detail: 'После того как обязательный хадж уже совершён хотя бы раз, повторные поездки для совершения хаджа считаются добровольным поклонением (нафль) и приносят награду, но не являются обязанностью. Учёные разошлись во мнении, что лучше: повторять нафль-хадж или потратить эти же средства на садаку нуждающимся — большинство современных муфтиев склоняются к тому, что помощь бедным родственникам и нуждающимся в тяжёлые для общины времена предпочтительнее многократного паломничества, если средства ограничены.\n\nХадис (Бухари 1773, Муслим 1349): «Умра за умрой — искупление того, что между ними, а хадж, принятый [Аллахом], не имеет иной награды, кроме Рая» — этот хадис не делает различия между первым и повторным хаджем в отношении награды, если оба совершены искренне и приняты Аллахом.\n\nПрактика: если у человека уже выполнена обязанность хаджа и он рассматривает повторную поездку, стоит взвесить, не нуждаются ли в этих же средствах близкие родственники или нуждающиеся соотечественники — с точки зрения многих учёных, это может принести больше пользы умме, чем дублирование уже выполненного столпа.',
        detailKk: 'Парыз хадж кемінде бір рет орындалғаннан кейін, хажға қайта бару ерікті ғибадат (нәпіл) саналады, сауап әкеледі, бірақ міндет емес. Ғалымдар не жақсы екені туралы пікірлерін бөлді: нәпіл-хажды қайталау ма, әлде сол қаражатты мұқтаждарға садақа беру ме — қазіргі муфтилердің көпшілігі қаражат шектеулі болса, қажет туыстар мен қауымның ауыр кезеңдеріндегі мұқтаждарға көмек көрсету бірнеше рет қажылық жасаудан артық деген пікірге бейім.\n\nХадис (Бухари 1773, Мүслім 1349): «Умрадан кейінгі умра — екеуінің арасындағыны өтейді, ал [Аллаһ] қабыл еткен хаждың сауабы Жәннаттан басқа ештеңе емес» — бұл хадис бірінші және қайталама хаждың сауабы арасында, екеуі де шынайы жасалып, Аллаһ қабыл етсе, айырмашылық жасамайды.\n\nТәжірибе: адамның хадж парызы бұрын орындалған болса және ол қайта баруды қарастырса, сол қаражатқа жақын туыстары немесе мұқтаж отандастары мұқтаж емес пе екенін өлшеп көрген жөн — көптеген ғалымдардың көзқарасы бойынша, бұл орындалған тіректі қайталаудан гөрі уммаға көбірек пайда әкелуі мүмкін.' }
    ];

    const HAJJ_CONDITIONS = [
      { title: 'Ислам', titleKk: 'Ислам',
        detail: 'Хадж — обязанность, возложенная только на мусульманина; от немусульманина обряд не принимается и не засчитывается как выполнение столпа ислама.\n\nХадис Джибриля (Муслим 8) перечисляет хадж в числе пяти столпов, построенных именно на исламе как предварительном условии — все столпы веры и практики адресованы тому, кто уже произнёс два свидетельства.\n\nИсторическое основание строгости этого условия — оглашение Абу Бакра (р.а.) на девятом году хиджры, когда по указанию Пророка ﷺ Али (р.а.) объявил паломникам: «После этого года ни один многобожник не совершит хадж, и никто не будет обходить Дом обнажённым» (Бухари 369, 4655) — с этого момента хадж окончательно закрепился как обряд, доступный только верующим в единого Аллаха.\n\nПрактика: если человек принял ислам во взрослом возрасте, поездка в Мекку до принятия ислама (например, в качестве туриста) не засчитывается — обязанность возникает заново с момента шахады; при этом уже принятый ислам не требует повторения других прежних актов поклонения, кроме хаджа, если он ещё не был совершён.',
        detailKk: 'Хадж — тек мұсылманға жүктелген міндет; мұсылман еместен бұл ғибадат қабылданбайды және исламның тірегін орындау деп есептелмейді.\n\nЖәбірейіл хадисі (Мүслім 8) хажды исламды алғышарт ретінде негіздей отырып, бес тірек қатарында тізбелейді — сенім мен амалдың барлық тіректері екі куәлікті айтқан адамға арналған.\n\nБұл шарттың қаттылығының тарихи негізі — хижраның тоғызыншы жылында Әбу Бәкірдің (р.а.) жариялауы, Пайғамбардың ﷺ нұсқауымен Әли (р.а.) қажыларға: «Бұл жылдан кейін ешбір мүшрік хадж жасамайды, әрі ешкім Үйді жалаңаш айналмайды» деп жариялаған (Бухари 369, 4655) — осы сәттен бастап хадж түпкілікті түрде тек жалғыз Аллаһқа сенушілерге ғана арналған ғұрып болып бекітілді.\n\nТәжірибе: адам ересек кезінде ислам қабылдаса, ислам қабылдамас бұрын Меккеге барған сапары (мысалы, турист ретінде) есептелмейді — міндет шаһада айтылған сәттен бастап қайта туындайды; сонымен қатар қабылданған ислам хаждан басқа бұрынғы ғибадат актілерін қайталауды талап етпейді, егер хадж әлі жасалмаған болса.' },
      { title: 'Разум (акль)', titleKk: 'Ақыл',
        detail: 'Человек, лишённый рассудка, не обязан совершать хадж — с него снята обязанность (калям), пока разум не восстановится.\n\nХадис (Абу Дауд 4403, хасан): «Перо снято с трёх: со спящего, пока не проснётся, с ребёнка, пока не достигнет совершеннолетия, и с безумного, пока не придёт в разум» — этот же хадис лежит в основе освобождения от намаза, поста и других столпов при потере рассудка.\n\nЕсли помрачение рассудка временное или периодическое (чередующиеся периоды ясности и безумия), обязанность действует именно на периоды ясного сознания — по мнению большинства факихов, ния и все обряды, совершённые в момент просветления, действительны в полной мере, как у здорового человека.\n\nПрактика: если расстройство временное — обязанность откладывается до восстановления дееспособности; при постоянной невменяемости хадж не обязателен и не может быть совершён «бадаль» при жизни человека, поскольку сама обязанность (истита‘а по разуму) для него никогда не возникает — в отличие от постоянно больного телом, за которого хадж-бадаль допустим (см. карточку «Хадж-бадаль»).',
        detailKk: 'Ақыл-есінен айырылған адамға хадж парыз емес — ақылы қалпына келгенше одан бұл міндет алынып тасталады.\n\nХадис (Әбу Дәуід 4403, хасан): «Қалам үшеуден алынған: ұйықтап жатқаннан — оянғанша, баладан — кәмелетке толғанша, және ақыл-есінен адасқаннан — ақылы қайта келгенше» — осы хадис намаз, ораза және басқа тіректерден ақыл-есі кеткен кезде босату негізінде жатыр.\n\nАқыл бұзылуы уақытша немесе кезеңдік (есі дұрыс пен адасу кезеңдері алма-кезек ауысатын) болса, міндет тек есі дұрыс кезеңдерге қатысты қолданылады — көп факиһтің пікірінше, есі дұрыс кезде жасалған ниет пен барлық ғұрып дені сау адамдікіндей толық жарамды.\n\nТәжірибе: бұзылу уақытша болса — мүмкіндігі қалпына келгенше міндет кейінге қалдырылады; тұрақты ақыл-есі кеткен жағдайда хадж парыз емес және адам тірі кезінде оны «бадал» ретінде жасауға болмайды, себебі оған істиғаат (ақыл жағынан мүмкіндік) ешқашан туындамайды — денесі тұрақты ауру адамнан айырмашылығы, оған хадж-бадал рұқсат етіледі («Хадж-бадал» карточкасын қараңыз).' },
      { title: 'Совершеннолетие (баллиг)', titleKk: 'Кәмелетке толу (баллиғ)',
        detail: 'Хадж ребёнка (с разрешения и в сопровождении опекуна) действителен как добровольный (нафль) и приносит награду, но не освобождает от обязательного хаджа после достижения совершеннолетия — его нужно совершить заново при появлении способности.\n\nХадис (Муслим 1336): женщина подняла ребёнка и спросила Пророка ﷺ: «Действителен ли хадж для этого?» — он ответил: «Да, и тебе — награда» — прямое подтверждение действительности детского хаджа как добровольного акта с наградой для сопровождающего родителя.\n\nСовершеннолетие (баллиг) определяется признаками: у мальчиков — поллюция (ихтилям) или появление волос на теле определённого рода, у девочек — начало менструации, а при отсутствии явных признаков большинство факихов ориентируется на возраст около пятнадцати лунных лет. Различают младенца, не способного к осознанному намерению (за него ния и обряды выполняет опекун — например, несёт его при тавафе), и различающего ребёнка (мумайиз), который с разрешения опекуна сам произносит намерение и выполняет действия хаджа при поддержке взрослого.\n\nПрактика: опекуну стоит помнить, что по достижении совершеннолетия и появлении возможности взрослый должен совершить обязательный хадж заново «за себя» — детский хадж в зачёт не идёт, но сам факт раннего паломничества с детства воспитывает привычку и любовь к обряду.',
        detailKk: 'Қамқоршының рұқсаты және сүйемелдеуімен жасалған баланың хажы ерікті (нәпіл) саналады және сауап әкеледі, бірақ кәмелетке толғаннан кейін парыз хаждан босатпайды — мүмкіндік туғанда оны қайта жасау керек.\n\nХадис (Мүслім 1336): бір нәзік жанды баланы көтеріп, Пайғамбардан ﷺ: «Осыған хадж жарамды ма?» — деп сұрады, ол: «Иә, әрі саған да сауап бар» деп жауап берді — бұл балалық хаждың ерікті амал ретінде жарамдылығын және сүйемелдеуші ата-анаға сауап әкелетінін тікелей растайды.\n\nКәмелетке толу (баллиғ) белгілермен анықталады: ұл балаларда — түсінде ырым болу (ихтиләм) немесе белгілі дене шашының пайда болуы, қыз балаларда — хайыздың басталуы, ал айқын белгілер болмаса, көп факиһ шамамен он бес қамар жылын негізге алады. Саналы ниетке қабілетсіз нәресте (оның ниеті мен ғұрпын қамқоршысы орындайды — мысалы, тауаф кезінде оны көтеріп жүреді) мен ажырата білетін бала (мумаиз) арасында айырмашылық бар, соңғысы қамқоршының рұқсатымен өз ниетін өзі айтады және хаж әрекеттерін ересектің қолдауымен орындайды.\n\nТәжірибе: қамқоршы есте сақтауы керек: кәмелетке толып, мүмкіндік туғанда ересек адам парыз хажды «өзі үшін» қайта жасауы керек — балалық хадж есепке кірмейді, бірақ балалық шақтан бастап ерте қажылыққа бару ғұрыпқа деген әдет пен сүйіспеншілікті тәрбиелейді.' },
      { title: 'Истита‘а (способность)', titleKk: 'Істиғаат (мүмкіндік)',
        detail: 'Три составляющих: (1) здоровье — способность физически перенести дорогу и обряды; (2) финансы — расходы на путь и содержание семьи на время отсутствия, без долгов, ухудшающих положение; (3) безопасность маршрута. Основание — Коран 3:97: «У Аллаха на людях обязанность хаджа к Дому — для того, кто способен проложить к нему путь».\n\nУчёные добавляют к трём составляющим и четвёртую, особую для женщины — наличие махрама (см. соответствующую карточку); отсутствие одного из условий не делает хадж запретным при желании его совершить, но снимает саму обязательность.\n\nФикх различает «истита‘а мубашара» — прямую способность совершить обряды собственным телом, и «истита‘а маль» — финансовую способность отправить вместо себя другого человека (хадж-бадаль) при постоянной физической неспособности. Основание для второго вида — хадис о женщине из племени Хас‘ам (Бухари 1513, Муслим 1334): она спросила Пророка ﷺ, обязателен ли хадж для её престарелого отца, который не может удержаться в седле, и получила ответ: «Да, соверши хадж за него» — прямое доказательство, что финансово способный, но телесно немощный человек обязан хаджем через доверенное лицо, а не освобождается полностью.\n\nПрактика: истита‘а оценивается на момент выезда группы, а не абстрактно — если средства и здоровье уже достаточны в этом году, откладывать хадж «на потом» без причины порицается большинством учёных, поскольку здоровье может внезапно ухудшиться; финансовая способность не требует продажи основного жилья или орудий заработка — учитываются лишь свободные средства сверх насущных нужд.',
        detailKk: 'Үш құрамдас бөлігі бар: (1) денсаулық — жол мен ғибадаттарды дене жағынан көтере алу; (2) қаржы — жол шығыны және жоқ кезінде отбасын асырауға, жағдайды нашарлататын қарызсыз; (3) жол қауіпсіздігі. Негізі — Құран 3:97 аяты: «Үйге дейін жол жүре алатын адамдарға Аллаһтың алдында хаж парыз».\n\nҒалымдар үш құрамдас бөлікке нәзік жандыға тән төртінші шартты да қосады — махрамның болуы (тиісті карточканы қараңыз); шарттардың бірінің болмауы хаждды жасауды тілеген адамға харам етпейді, тек оның міндеттілігін алып тастайды.\n\nФикх «істиғаат мубашара» — өз денесімен ғұрыпты орындай алу қабілетін, және «істиғаат мал» — тұрақты дене әлсіздігі кезінде өзінің орнына басқа адамды жіберу (хадж-бадал) қаржылық қабілетін ажыратады. Соңғысының негізі — Хас‘ам тайпасынан шыққан нәзік жанды туралы хадис (Бухари 1513, Мүслім 1334): ол Пайғамбардан ﷺ ер тоқымда отыра алмайтын қарт әкесіне хадж парыз бе деп сұрады, әрі: «Иә, оның орнына хадж жаса» деген жауап алды — бұл қаржылық жағынан мүмкіндігі бар, бірақ дене жағынан әлсіз адамның хажы толығымен алынбай, сенімді адам арқылы міндетті болатынының тікелей дәлелі.\n\nТәжірибе: істиғаат топ аттанар кезде бағаланады, дерексіз емес — егер осы жылы қаражат пен денсаулық жеткілікті болса, хаждды себепсіз «кейінге» қалдыру көп ғалым тарапынан айыпталады, себебі денсаулық кенеттен нашарлауы мүмкін; қаржылық мүмкіндік негізгі тұрғын үй немесе күнкөріс құралдарын сатуды талап етпейді — тек негізгі қажеттіліктен артық бос қаражат есепке алынады.' },
      { title: 'Махрам для женщины', titleKk: 'Нәзік жандыға махрам',
        detail: 'По мнению большинства мазхабов, женщина отправляется в хадж только с махрамом (мужем или близким родственником, за которого ей запрещён брак). Ряд современных фетв (в том числе некоторых официальных комитетов после 2021 года) допускают поездку организованной женской группой без махрама при соблюдении условий безопасности — вопрос остаётся предметом иджтихада, стоит уточнять у местного духовного управления.\n\nХадис (Бухари 1862, Муслим 1341): Пророк ﷺ сказал: «Пусть женщина не отправляется в путь длиной в один день пути, кроме как с махрамом» — ранние учёные распространили этот принцип на любой дальний путь, включая хадж, из заботы о безопасности женщины в дороге.\n\nМазхабы расходятся в строгости условия: ханафиты и ханбалиты требуют махрама как обязательное условие самой обязательности хаджа для женщины (без него хадж не становится фард для неё, хотя, совершив его, она получает награду); маликиты и часть шафиитов допускают выезд с группой надёжных, благочестивых женщин или даже одной надёжной спутницей при отсутствии реальной опасности, считая безопасность, а не именно родство, сутью хадиса.\n\nПрактика: если официальная фетва местного духовного управления допускает женскую группу без махрама, стоит убедиться, что группа действительно организованная — с проверенным турагентством, старшей по группе и средствами связи; пожилым женщинам, чей возраст и обстоятельства снижают риск, некоторые современные муфтии дают дополнительное облегчение.',
        detailKk: 'Көп мазһаб бойынша нәзік жанды хаджға тек махраммен (күйеуі немесе некесі харам жақын туысы) барады. Кейбір қазіргі фетуалар (соның ішінде 2021 жылдан кейінгі бірқатар ресми комитеттер) қауіпсіздік шарттары сақталса, ұйымдастырылған нәзік жандылар тобымен махрамсыз баруға рұқсат етеді — бұл мәселе әлі де ижтихад мәселесі, жергілікті діни басқармадан нақтылаған жөн.\n\nХадис (Бухари 1862, Мүслім 1341): Пайғамбар ﷺ: «Нәзік жанды махрамсыз бір күндік жол сапарға шықпасын» деген — ерте ғалымдар бұл қағиданы хаджды қоса алғанда кез келген алыс жолға, жолдағы нәзік жандының қауіпсіздігіне алаңдап, таратқан.\n\nМазһабтар шарттың қаттылығында алшақтайды: ханафи және ханбали мазхабтары махрамды нәзік жандыға хаждың міндеттілігінің өзінің шарты деп талап етеді (онсыз хадж оған парыз болмайды, дегенмен жасаса, сауап алады); малики және шафиидің бір бөлігі нақты қауіп болмаса, сенімді, тақуа нәзік жандылар тобымен немесе тіпті бір сенімді серіктеспен баруға рұқсат етеді, хадистің мәні туыстықта емес, қауіпсіздікте деп санайды.\n\nТәжірибе: жергілікті діни басқарманың ресми фетуасы махрамсыз нәзік жандылар тобына рұқсат етсе, топтың шынымен ұйымдастырылған екеніне көз жеткізу керек — тексерілген турагенттік, топ жетекшісі және байланыс құралдарымен; жасы мен жағдайы қауіпті азайтатын егде нәзік жандыларға кейбір қазіргі мүфтилер қосымша жеңілдік береді.' },
      { title: 'Свобода (не раб)', titleKk: 'Азаттық (құл еместік)',
        detail: 'Классическое условие фикха: хадж не обязателен для раба, даже если он телесно здоров и формально имел бы средства, — поскольку его время и имущество принадлежат хозяину, а не ему самому. Сегодня рабства как правового института не существует, поэтому условие имеет в основном историческое и теоретическое значение, но остаётся частью классического перечня условий обязательности хаджа.\n\nОснование — общий принцип фикха о правовом статусе раба, чьи действия и распоряжение временем подчинены владельцу; большинство ранних факихов включало свободу в число условий именно по аналогии с условиями обязательности пятничной молитвы и закята, где раб также освобождён.\n\nЕсли раб всё же совершил хадж с разрешения хозяина, обряд засчитывается ему как добровольный (нафль), подобно хаджу несовершеннолетнего, — а после освобождения из рабства обязательный хадж нужно совершить заново при появлении способности, если раб получил свободу и стал полностью дееспособным мусульманином.\n\nПрактика: в современном мире условие фактически неактуально для подавляющего большинства мусульман, но упоминается в классических учебниках фикха для полноты перечня столпов обязательности и по аналогии применяется факихами к близким по смыслу современным ситуациям несвободного распоряжения собой (например, обсуждается применительно к некоторым формам долговой кабалы).',
        detailKk: 'Классикалық фикх шарты: хадж құлға парыз емес, тіпті ол дене жағынан сау болып, формальды түрде қаражаты болса да — себебі оның уақыты мен мүлкі қожайынына тиесілі, өзіне емес. Бүгінде құлдық құқықтық институт ретінде жоқ, сондықтан бұл шарттың негізінен тарихи және теориялық маңызы бар, бірақ ол хаждың міндеттілігінің классикалық шарттарының тізімінің бір бөлігі болып қала береді.\n\nНегізі — құлдың құқықтық мәртебесі туралы фикхтің жалпы қағидасы, оның әрекеттері мен уақытын билеуі иесіне бағынышты; көп ерте факиһ азаттықты жұма намазы мен зекеттің міндеттілік шарттарына ұқсастық бойынша қосқан, онда да құл босатылған.\n\nЕгер құл иесінің рұқсатымен хадж жасаса да, бұл оған ерікті (нәпіл) ретінде есептеледі, кәмелетке толмаған баланың хажы сияқты — құлдықтан босатылғаннан кейін мүмкіндік туғанда парыз хажды қайта жасау керек, егер құл азаттық алып, толық құқылы мұсылман болса.\n\nТәжірибе: қазіргі әлемде бұл шарт мұсылмандардың басым көпшілігіне іс жүзінде маңызды емес, бірақ классикалық фикх оқулықтарында міндеттілік тіректерінің тізімінің толықтығы үшін аталады және факиһтер оны мағынасы жақын қазіргі жағдайларға (мысалы, кейбір қарыз құлдығы формаларына қатысты талқыланады) ұқсастық бойынша қолданады.' },
      { title: 'Хадж-бадаль (за неспособного или умершего)', titleKk: 'Хадж-бадал (мүмкіндігі жоқ немесе қайтыс болған үшін)',
        detail: 'Если человек финансово способен, но постоянно и необратимо не может совершить хадж лично (тяжёлая старость, хроническая болезнь) или умер, не исполнив обязательный хадж, разрешается отправить вместо себя другого человека — за собственный счёт, из наследства или через благотворительную организацию.\n\nХадис о женщине из племени Хас‘ам (Бухари 1513, Муслим 1334) — основа для случая живого, но немощного человека: Пророк ﷺ разрешил ей совершить хадж за отца, который «не может удержаться в седле». Отдельный хадис (Бухари 1852, Ибн Аббас) — основа для случая умершего: женщина спросила о матери, умершей с невыполненным обетом хаджа, и Пророк ﷺ велел ей выполнить обет за мать, сравнив это с выплатой долга умершего.\n\nВажное условие для самого заместителя (нанимаемого паломника): по хадису Ибн Аббаса (Абу Дауд 1811) Пророк ﷺ, услышав, как человек произносит тальбию «Ляббайка ‘ан Шубрума», спросил, совершил ли он хадж за себя, и, узнав, что нет, велел: «Соверши хадж за себя, потом за Шубрума» — большинство учёных вывели отсюда, что заместитель должен сначала выполнить собственный обязательный хадж, прежде чем совершать хадж за другого.\n\nПрактика: при найме через официальные хадж-агентства стоит убедиться, что подрядчик действительно уже совершил свой обязательный хадж и что оплата и обряд документируются — во избежание мошенничества с «хаджем за умершего родственника», встречающегося на неофициальном рынке услуг.',
        detailKk: 'Адам қаржы жағынан мүмкіндігі бар, бірақ тұрақты және қайтымсыз түрде хажды өзі жасай алмаса (ауыр қарттық, созылмалы ауру) немесе парыз хажды орындамай қайтыс болса, өз есебінен, мұрадан немесе қайырымдылық ұйымы арқылы өз орнына басқа адамды жіберуге рұқсат етіледі.\n\nХас‘ам тайпасынан шыққан нәзік жанды туралы хадис (Бухари 1513, Мүслім 1334) — тірі, бірақ әлсіз адам жағдайының негізі: Пайғамбар ﷺ оған «ер тоқымда отыра алмайтын» әкесі үшін хадж жасауға рұқсат берді. Бөлек хадис (Бухари 1852, Ибн Аббас) — қайтыс болған адам жағдайының негізі: бір нәзік жанды хадж нәзірін орындамай қайтыс болған анасы туралы сұрады, Пайғамбар ﷺ оған анасы үшін нәзірді орындауды бұйырды, мұны қайтыс болғанның қарызын өтеумен салыстырды.\n\nОрынбасардың (жалданған қажының) өзіне қатысты маңызды шарт: Ибн Аббас хадисі бойынша (Әбу Дәуід 1811) Пайғамбар ﷺ бір адамның «Ляббайка ‘ан Шубрума» деп тәлбия айтқанын естіп, оның өзі хадж жасаған-жасамағанын сұраған, жасамағанын білгенде: «Алдымен өзің үшін хадж жаса, содан кейін Шубрума үшін» деп бұйырған — көп ғалым осыдан орынбасар алдымен өзінің парыз хажын орындауы керек деп шығарған.\n\nТәжірибе: ресми хадж агенттіктері арқылы жалдағанда, мердігердің шынымен өз парыз хажын жасағанына және төлем мен ғұрыптың құжатталатынына көз жеткізген жөн — бейресми қызмет нарығында кездесетін «қайтыс болған туысқа хадж» алаяқтығынан сақтану үшін.' }
    ];

    const HAJJ_IHRAM_RULES = [
      { title: 'Близость и её прелюдии', titleKk: 'Жақындық және оның алдыңғы әрекеттері',
        detail: 'Самое строгое ограничение ихрама — половая близость и всё, что к ней ведёт (объятия и разговоры со страстью). Коран 2:197 называет это «рафас» и запрещает во время хаджа.\n\nПолноценная близость до первого снятия ограничений (тахаллюль авваль) делает хадж действительным, но требует восполнения в следующем году (см. карточку «Фидья за нарушения»), тогда как поцелуи и прикосновения со страстью без самой близости требуют лишь фидьи, без аннулирования хаджа.\n\nПосле первого тахаллюля (после халяка/таксара) большинство запретов ихрама снимаются — можно надевать обычную одежду, стричь волосы, пользоваться парфюмом, — но именно половая близость остаётся под запретом вплоть до второго тахаллюля, наступающего после тавафа ифада. Это единственный запрет, действующий на всём протяжении обоих этапов ихрама.\n\nПрактика: супругам, совершающим хадж вместе, стоит заранее договориться о временном воздержании от нежностей на весь период ихрама, вплоть до второго тахаллюля после тавафа ифада, и не откладывать таваф ифада намеренно дольше необходимого, чтобы не продлевать этот период ограничения без нужды.',
        detailKk: 'Ихрамның ең қатаң шектеуі — жыныстық жақындық және оған апаратын нәрсе (құштарлықпен құшақтасу, әңгіме). Құран 2:197 аятында бұл «рафас» деп аталып, хаждда тыйым салынады.\n\nБірінші шектеуден босаудан (тахаллюль-и әууал) бұрын толық жақындық хаждды жарамсыз етпейді, бірақ келесі жылы толтыруды талап етеді («Бұзғаны үшін фидия» карточкасын қараңыз), ал жақындықсыз құштарлықпен сүю мен қол тигізу тек фидияны талап етеді, хаждды жоймайды.\n\nБірінші тахаллюльден кейін (қырыну/қысқартудан кейін) ихрамның көп тыйымдары алынады — әдеттегі киім киюге, шаш қиюға, хош иіс жағуға болады — бірақ дәл жыныстық жақындық тауаф ифададан кейін келетін екінші тахаллюльге дейін тыйым астында қалады. Бұл — ихрамның екі кезеңінің бүкіл ұзақтығында қолданылатын жалғыз тыйым.\n\nТәжірибе: бірге хадж жасайтын жұбайларға ихрам кезеңінің бүкіл уақытында, тауаф ифададан кейінгі екінші тахаллюльге дейін, еркелетуден уақытша бас тарту туралы алдын ала келісіп алғаны және тауаф ифаданы қажетінен артық созбай орындағаны жөн, бұл шектеу кезеңін бекерге ұзартпас үшін.' },
      { title: 'Грех и ссора (фусук, джидаль)', titleKk: 'Күнә мен дау-дамай (фусук, жидал)',
        detail: 'Коран 2:197: «Кто обязал себя хаджем в эти месяцы, пусть не будет ни рафаса, ни фусука (греха), ни джидаля (ссоры) в хадже». Паломнику стоит быть особенно терпеливым и мягким.\n\nХадис (Бухари 1521): «Кто совершил хадж для Аллаха и не осквернил его [рафасом] и не совершил нечестия [фусук], тот вернётся [чистым от грехов], как в тот день, когда его родила мать» — награда хаджа связана именно с воздержанием от рафаса, фусука и джидаля, а не только с правильным исполнением обрядов.\n\nУчёные поясняют «джидаль» не как любой спор в принципе (обсуждение фикха или уточнение маршрута не входит в запрет), а как перепалку из гордости, упрямый спор ради победы в споре или пустые препирательства о датах и деталях, не имеющие практической пользы, — сама сущность запрета в разрушительности спора для сердца паломника, а не в самом факте разговора о разногласиях.\n\nПрактика: в условиях жары, усталости и толчеи раздражение — обычное искушение; полезно заранее настроиться прощать толкающих в толпе людей и не спорить с соседями по лагерю из-за бытовых мелочей, а также беречь язык от жалоб и пересудов, которые тоже относятся к духу «фусука», подрывающего смысл паломничества.',
        detailKk: 'Құран 2:197 аяты: «Осы айларда хаждды өзіне парыз еткен адам хаждда рафас та, фусук та (күнә), жидал да (дау-дамай) жасамасын». Қажыға әсіресе сабырлы әрі жұмсақ болу жарасады.\n\nХадис (Бухари 1521): «Кім Аллаһ үшін хадж жасап, оны [рафаспен] арамдамаса және [фусук] нечестие жасамаса, ол [күнәдан таза] анасынан туған күндегідей қайтады» — хаждың сауабы дәл рафастан, фусуктан және жидалдан бас тартумен байланысты, тек ғұрыптарды дұрыс орындаумен ғана емес.\n\nҒалымдар «жидалды» жалпы кез келген дау-дамай ретінде емес (фикх мәселесін талқылау немесе маршрутты нақтылау тыйымға кірмейді), мақтаныштан туындаған тартыс, жеңу үшін қасарысқан дау немесе күн мен ұсақ детальдар туралы пайдасыз керіліс ретінде түсіндіреді — тыйымның мәні әңгіме фактісінде емес, дау-дамайдың қажының жүрегіне келтіретін бүлдіргіш әсерінде.\n\nТәжірибе: ыстық, шаршау және кептеліс жағдайында ашуланшақтық — әдеттегі азғыру; тобырда итеретін адамдарды кешіруге және лагерь көршілерімен тұрмыстық ұсақ-түйек үшін дауласпауға алдын ала дайын болған пайдалы, сондай-ақ шағым мен өсекке де тілді сақтау керек — бұл да қажылықтың мәнін бұзатын «фусук» рухына жатады.' },
      { title: 'Охота на сухопутную дичь', titleKk: 'Құрлықтағы аңды аулау',
        detail: 'Запрет охоты действует только на суше (5:95–96); рыбная ловля и морепродукты разрешены. За нарушение — компенсация подобным домашним животным или его стоимостью в виде еды либо поста.\n\nКоран (5:95): «А кто из вас убьёт её [дичь] преднамеренно, тому воздаяние — подобное тому, что он убил, из скота, как решат два справедливых человека из вас, в виде жертвы, доставленной к Каабе» — компенсация оценивается через двух знающих свидетелей, а не произвольно.\n\nХадис Абу Катады (Бухари 1824, Муслим 1196): будучи вне ихрама, он подстрелил дикого осла и принёс мясо спутникам, находившимся в ихраме; когда они усомнились, можно ли им это есть, Пророк ﷺ спросил, указывал ли кто-то из них охотнику на добычу или помогал ему, и, узнав, что нет, разрешил есть мясо — запрет касается именно личной охоты и содействия ей, но не употребления в пищу дичи, добытой кем-то другим без их участия и указания.\n\nПрактика: запрет касается и наведения других на охоту (например, указания охотнику на дичь) — стоит избегать даже разговоров об охоте на суше в границах харама; насекомых и вредителей (комаров, вшей, скорпионов), не относящихся к дичи, разрешено убивать при необходимости.',
        detailKk: 'Аулауға тыйым тек құрлыққа қатысты (5:95–96 аяттары); балық аулау мен теңіз өнімдеріне рұқсат. Бұзғаны үшін — соған ұқсас үй жануарымен немесе оның құнына тең тамақ не ораза түрінде өтеу.\n\nҚұран (5:95): «Ал сендерден кім оны [аңды] әдейі өлтірсе, оның өтемі — өлтірген аңға ұқсас, сендерден екі әділ адам шешетін мал түрінде, Қағбаға жеткізілетін құрбандық болады» — өтем еркінше емес, білікті екі куә арқылы бағаланады.\n\nӘбу Қатада хадисі (Бухари 1824, Мүслім 1196): ихрамда болмай тұрып, ол жабайы есекті атып алып, ихрамдағы серіктеріне етін әкелген; олар оны жеуге бола ма деп күдіктенгенде, Пайғамбар ﷺ олардың біреуі аңшыға аңды көрсеткен бе немесе көмектескен бе деп сұраған, жоқ екенін білгенде, етті жеуге рұқсат берген — тыйым дәл жеке аулауға және оған көмектесуге қатысты, ал басқа адам олардың қатысуы мен көрсетуінсіз аулаған аңды жеуге емес.\n\nТәжірибе: тыйым басқаларды аулауға бағыттауды да қамтиды (мысалы, аңшыға аңды көрсету) — харам шекарасында құрлықта аулау туралы әңгімеден де аулақ болған жөн; аң санатына жатпайтын жәндіктер мен зиянкестерді (масалар, бит, шаяндар) қажет болғанда өлтіруге рұқсат етіледі.' },
      { title: 'Ногти, волосы, парфюм', titleKk: 'Тырнақ, шаш, хош иіс',
        detail: 'После вступления в ихрам запрещены: срезание ногтей, удаление волос с любой части тела (бритьё, выщипывание), нанесение парфюма и благовоний на тело или одежду. Умащение до намерения (перед произнесением ихрама) разрешено и является сунной.\n\nХадис (Бухари 1539, Муслим 1190): Аиша (р.а.) рассказывала, что умащала Пророка ﷺ благовониями перед его вступлением в ихрам, «и я как будто вижу блеск благовония на его пробритой части головы и бороде» — прямое основание сунны умащения именно до, а не после произнесения намерения.\n\nВолосы, выпавшие непреднамеренно во время омовения или мытья головы (например, при расчёсывании пальцами по сунне гусля), не считаются нарушением — запрещено именно осознанное удаление волос действием, направленным на это; сломанный или обломившийся ноготь можно подровнять, если это причиняет боль или мешает, поскольку устранение вреда для тела не входит в цель запрета.\n\nПрактика: если запах благовония, нанесённого до ихрама, остаётся ощутимым уже после вступления в ихрам, это не считается нарушением — запрещено именно новое нанесение парфюма; мыло и шампунь без выраженного парфюмерного запаха допустимы для мытья тела и головы в ихраме.',
        detailKk: 'Ихрамға кіргеннен кейін: тырнақ алу, дене шашын кетіру (қырыну, жұлу), денеге не киімге хош иіс жағу тыйым салынады. Ниет алдында (ихрам айтылмас бұрын) хош иіс жағу рұқсат және сүннет болып саналады.\n\nХадис (Бухари 1539, Мүслім 1190): Аиша (р.а.) Пайғамбарды ﷺ ихрамға кірер алдында хош иіспен майлағанын, «мен оның қырылған басы мен сақалындағы хош иістің жарқырауын көріп тұрғандай едім» деп айтқан — бұл ниет айтылмас бұрын, кейін емес, дәл алдында майлау сүннетінің тікелей негізі.\n\nДәрет немесе бас жуу кезінде (мысалы, ғұсылдың сүннеті бойынша саусақпен тарау кезінде) байқаусызда түскен шаш бұзушылық саналмайды — тыйым салынғаны дәл осыған бағытталған әрекетпен саналы шаш кетіру; сынған немесе үзілген тырнақты, ауырса немесе кедергі жасаса, теңестіруге болады, себебі денеге зиянды жоюдың өзі тыйымның мақсатына кірмейді.\n\nТәжірибе: ихрамға дейін жағылған хош иіс ихрамға кіргеннен кейін де сезілсе, бұл бұзушылық саналмайды — тыйым салынғаны дәл жаңадан хош иіс жағу; ихрамда денені және бас шашты жуу үшін хош иісі айқын білінбейтін сабын мен шампунь рұқсат етіледі.' },
      { title: 'Брачный договор', titleKk: 'Неке қию',
        detail: 'В состоянии ихрама нельзя заключать брачный договор — ни для себя, ни выступая свидетелем или представителем (вакилем) в чужом браке. Сам брак (никах) в ихраме считается недействительным.\n\nХадис (Муслим 1409): «Не заключает никах находящийся в ихраме, и не сватается» — прямой запрет, из которого учёные вывели недействительность самого договора, а не просто греховность действия.\n\nПоскольку сам договор считается недействительным, а не просто грехом, за это нарушение не назначается фидья — в отличие от таких действий, как срезание волос или нанесение парфюма, которые остаются действительными фактами, требующими компенсации, никах в ихраме юридически как бы не состоялся вовсе и должен быть заключён заново после выхода из ихрама, если стороны всё ещё желают вступить в брак.\n\nПрактика: если предложение руки и сердца случайно возникло во время хаджа, стоит явно отложить любые официальные шаги до выхода из ихрама, чтобы не пришлось аннулировать уже заключённый никах; обсуждение и предварительная договорённость о будущем браке без формального заключения договора запретом не затрагиваются.',
        detailKk: 'Ихрам кезінде неке қиюға болмайды — өзіне де, біреудің некесіне куә не өкіл (уәкіл) болып та. Ихрамда қиылған неке жарамсыз саналады.\n\nХадис (Мүслім 1409): «Ихрамдағы адам неке қимайды және құда түспейді» — тікелей тыйым, одан ғалымдар тек әрекеттің күнәлілігін емес, келісімнің өзінің жарамсыздығын шығарған.\n\nКелісімнің өзі жарамсыз саналатындықтан, жай күнә емес, бұл бұзушылық үшін фидия тағайындалмайды — шаш кесу немесе хош иіс жағу сияқты, нақты орын алған факт ретінде қалатын және өтем талап ететін әрекеттерден айырмашылығы, ихрамдағы неке заңды түрде мүлде болмағандай саналады және екі тарап әлі некеге отырғысы келсе, ихрамнан шыққаннан кейін қайта қиылуы керек.\n\nТәжірибе: хадж кезінде кездейсоқ құда түсу ұсынысы туындаса, ихрамнан шыққанға дейін кез келген ресми қадамдарды нақты кейінге қалдырған жөн, қиылған некені жоюға тура келмес үшін; болашақ неке туралы талқылау мен алдын ала келісім, ресми қиылмаса, тыйымға жатпайды.' },
      { title: 'Только мужчинам: покрытие головы и одежда', titleKk: 'Тек ерлерге: бас жабу және киім',
        detail: 'Мужчинам запрещено покрывать голову тканью вплотную (кепка, капюшон, полотенце) — тень зонта, машины или навеса разрешена. Нельзя носить сшитую по форме тела одежду (рубашки, брюки, носки) — только два несшитых полотнища и открытые сандалии.\n\nХадис (Бухари 134, Муслим 1177): на вопрос, что можно надевать в ихраме, Пророк ﷺ перечислил запрещённое — рубашки, чалмы, штаны, капюшоны и закрытую обувь — и уточнил, что у кого нет изара, может надеть штаны, а у кого нет сандалий — носить кожаные носки, обрезав их ниже щиколотки.\n\nБелый цвет изара и риды — сунна, а не строгое обязательное условие: большинство учёных разрешают ихрам любого чистого, немаркого цвета, хотя белый предпочтителен по примеру Пророка ﷺ и практичен в жару. Полотнища ихрама можно менять, стирать и заменять новыми в течение всего хаджа — само действие смены одежды нарушением не является, в отличие от кроя одежды по форме тела.\n\nПрактика: солнцезащитные очки, часы и пояс для денег без сшитых карманов, охватывающих тело, разрешены — запрет касается именно кроя одежды по форме тела; ходить в обычной закрытой обуви нельзя, даже если она не сшита, — важен именно охват стопы, а не техника пошива.',
        detailKk: 'Ерлерге басты матамен тығыз жабуға болмайды (кепка, капюшон, сүлгі) — күн шатыры, көлік немесе төбенің көлеңкесі рұқсат. Дене пішініне тігілген киім (көйлек, шалбар, шұлық) кимейді — тек тігілмеген екі мата және ашық сандал.\n\nХадис (Бухари 134, Мүслім 1177): ихрамда нені киюге болатыны туралы сұраққа Пайғамбар ﷺ тыйым салынғандарды тізбелеген — көйлек, сәлде, шалбар, капюшон және жабық аяқкиім — және изары жоқ адам шалбар кие алатынын, сандалы жоқ адам тобығынан төмен кесілген тері шұлық кие алатынын нақтылаған.\n\nИзар мен риданың ақ түсі — сүннет, қатаң міндетті шарт емес: көп ғалым таза, кірлемейтін кез келген түсті ихрамға рұқсат етеді, дегенмен ақ түс Пайғамбардың ﷺ үлгісі бойынша артықшылықты әрі ыстықта тәжірибелі. Ихрам матасын хаждың бүкіл кезеңінде ауыстыруға, жууға және жаңасына алмастыруға болады — киімді ауыстырудың өзі бұзушылық емес, дене пішініне тігілген киімнен айырмашылығы.\n\nТәжірибе: күннен қорғайтын көзілдірік, сағат және денеге тар тігілмеген қалталары жоқ ақша белдігі рұқсат етіледі — тыйым дәл дене пішініне тігілген киімге қатысты; тігілмеген болса да, әдеттегі жабық аяқкиіммен жүруге болмайды — маңыздысы дәл тігу техникасы емес, аяқты жабу.' },
      { title: 'Только женщинам: лицо и руки', titleKk: 'Тек нәзік жандыларға: бет және қол',
        detail: 'Женщинам запрещено закрывать лицо никабом и кисти рук перчатками — лицо и кисти должны быть открыты. При наличии посторонних мужчин допускается прикрыть лицо накидкой или платком, не прилегающим к коже вплотную. Обычная скромная одежда любого цвета разрешена — специальной белой формы для женщин нет.\n\nХадис (Бухари 1838): «Пусть женщина, находящаяся в ихраме, не закрывает лицо никабом и не надевает перчатки» — запрет специфичен именно для состояния ихрама и не отменяет обычные нормы хиджаба вне его.\n\nВолосы и тело женщина по-прежнему обязана покрывать обычной одеждой, как и вне ихрама, — запрет касается только лица и кистей рук, специально сшитых по их форме покрытий (никаб, перчатки); чулки и носки на ногах женщине разрешены и нарушением не считаются, поскольку запрет для женщины касается только лица и кистей, а не всей одежды, как у мужчин.\n\nПрактика: многие современные учёные разрешают женщине опускать край платка на лицо, не закрепляя его как никаб, при прохождении рядом с посторонними мужчинами — это не противоречит запрету на именно сшитый по форме лица никаб; лак для ногтей и украшения на теле ихрамом не запрещены, но должны соответствовать общим нормам скромности.',
        detailKk: 'Нәзік жандыларға бетті нікабпен, қолды қолғаппен жабуға тыйым салынады — бет пен қол ашық болуы керек. Бөгде ер адамдар болса, теріге тимейтін жамылғы немесе орамалмен бетті жабуға рұқсат. Кез келген түстегі қарапайым, әдепті киім рұқсат — нәзік жандыларға арнайы ақ түсті киім талап етілмейді.\n\nХадис (Бухари 1838): «Ихрамдағы нәзік жанды бетін нікабпен жаппасын және қолғап кимесін» — тыйым нақты ихрам күйіне тән, одан тыс кездегі әдеттегі хиджаб нормаларын жоймайды.\n\nШаш пен денені нәзік жанды ихрамнан тыс кездегідей әдеттегі киіммен жабуға міндетті — тыйым тек бет пен қолға, олардың пішініне арнайы тігілген жабындарға (нікаб, қолғап) қатысты; аяқтағы шұлық пен байпаққа рұқсат етіледі және бұзушылық саналмайды, себебі нәзік жандыға тыйым тек бет пен қолға қатысты, ерлердегідей бүкіл киімге емес.\n\nТәжірибе: көптеген қазіргі ғалымдар бөгде ер адамдардың жанынан өткенде, нәзік жандыға орамал шетін нікаб етіп бекітпей, бетіне түсіруге рұқсат етеді — бұл дәл бет пішініне тігілген нікабқа тыйым салуға қайшы келмейді; тырнаққа лак пен денедегі әшекейлер ихраммен тыйым салынбайды, бірақ жалпы әдептілік нормаларына сай болуы керек.' },
      { title: 'Растительность и деревья Харама', titleKk: 'Харам өсімдігі мен ағаштары',
        detail: 'Запрет касается не только состояния ихрама, но и границ священной территории (харам) вокруг Мекки в целом: запрещено срубать деревья, вырывать с корнем траву и растения харама — как для находящихся в ихраме, так и для местных жителей вне его.\n\nХадис (Бухари 1587, в день взятия Мекки): Пророк ﷺ сказал: «Поистине, эту землю Аллах сделал заповедной в день сотворения небес и земли, и она заповедна по заповеди Аллаха до Судного дня: не срубают её колючий кустарник, не вспугивают её дичь, не поднимают найденное, кроме как для объявления о находке, и не срывают её зелень» — на что аль-Аббас (р.а.) попросил исключение для идхира (душистой травы), используемой кузнецами и для крыш домов, и Пророк ﷺ разрешил именно это растение.\n\nЗапрет не связан с самим ихрамом — он действует для любого человека на территории харама, включая постоянных жителей Мекки, круглый год, а не только во время хаджа или умры; это отдельная категория запретов святости места, а не запретов состояния паломника.\n\nПрактика: за нарушение (срубленное дерево, вырванное растение) большинство учёных предписывают компенсацию в виде милостыни, соразмерной причинённому ущербу, а не фиксированную фидью, как за нарушения самого ихрама; выращенные человеком декоративные и сельскохозяйственные растения харама (посаженные и ухаживаемые, а не дикорастущие) под этот запрет не подпадают.',
        detailKk: 'Тыйым тек ихрам күйіне ғана емес, жалпы Мекке айналасындағы қасиетті аумақ (харам) шекарасына да қатысты: ихрамдағыларға да, одан тыс жергілікті тұрғындарға да харам ағаштарын кесу, шөп пен өсімдігін түбірімен жұлу тыйым салынған.\n\nХадис (Бухари 1587, Меккені жаулап алған күні): Пайғамбар ﷺ: «Расында, бұл жерді Аллаһ көктер мен жерді жаратқан күні қасиетті еткен, ол Аллаһтың бұйрығымен Қиямет күніне дейін қасиетті: оның тікенді бұтасы кесілмейді, аңы үркітілмейді, тапқан заты жариялау үшін болмаса алынбайды, әрі оның жасылы жұлынбайды» деген — оған Аббас (р.а.) ұсталар мен үй шатырлары үшін пайдаланылатын идхир (хош иісті шөп) үшін ерекшелік сұраған, Пайғамбар ﷺ дәл осы өсімдікке рұқсат берген.\n\nТыйым ихрамның өзімен байланысты емес — ол харам аумағында тұратын кез келген адамға, соның ішінде Мекке тұрғындарына, жыл бойы, тек хадж немесе умра кезінде ғана емес қолданылады; бұл — қажы күйінің тыйымы емес, орынның қасиеттілігінің бөлек санатты тыйымы.\n\nТәжірибе: бұзушылық үшін (кесілген ағаш, жұлынған өсімдік) көп ғалым ихрамның өз бұзушылықтарындағыдай белгілі фидия емес, келтірілген зиянға сай садақа өтемін тағайындайды; адам өсірген харамдағы сәндік және егіншілік өсімдіктер (жабайы емес, отырғызылған және күтілген) бұл тыйымға жатпайды.' },
      { title: 'Нарушение по незнанию, забывчивости или принуждению', titleKk: 'Білместік, ұмытшақтық немесе мәжбүрлікпен бұзу',
        detail: 'Фикх различает умышленное нарушение запретов ихрама и нарушение по забывчивости, незнанию или принуждению (например, ветром сорвало ткань, случайно порезал ноготь, забыл и понюхал духи по привычке). Общий принцип облегчения в шариате смягчает ответственность за непреднамеренные действия.\n\nОснование — Коран 2:286: «Господь наш, не взыщи с нас, если мы забыли или ошиблись» — этот аят паломники часто вспоминают как общий принцип, а также хадис о снятии ответственности за ошибку, забывчивость и принуждение с общины Пророка ﷺ (Ибн Маджа 2043, хасан).\n\nМазхабы расходятся в применении принципа к фидье: шафииты и часть ханбалитов освобождают от фидьи за нарушения, вызванные подлинной забывчивостью или незнанием (кроме компенсации за охоту и порчу растительности харама, где фидья требуется независимо от намерения, поскольку это право третьей стороны — живой природы и харама, а не только личная обязанность паломника), тогда как ханафиты и маликиты в большинстве случаев требуют фидью независимо от намерения, считая, что сама фидья — не наказание за грех, а компенсация за нарушение состояния ихрама как таковое.\n\nПрактика: если нарушение произошло случайно, стоит немедленно прекратить действие, как только вспомнил или узнал о запрете (например, снять зашитую одежду, смыть парфюм), и уточнить у сопровождающего алима согласно своему мазхабу, требуется ли фидья в конкретном случае — единого мнения для всех школ здесь нет.',
        detailKk: 'Фикх ихрам тыйымдарын әдейі бұзу мен ұмытшақтықпен, білместікпен немесе мәжбүрлікпен бұзуды ажыратады (мысалы, желмен матасы ашылып қалды, кездейсоқ тырнағын кесіп алды, әдетпен иіс суды иіскеп жіберді). Шариғаттағы жеңілдіктің жалпы қағидасы мақсатсыз әрекеттерге жауапкершілікті жеңілдетеді.\n\nНегізі — Құран 2:286 аяты: «Раббымыз, ұмытсақ немесе қателессек, бізді жазаламашы» — қажылар мұны жиі жалпы қағида ретінде еске алады, сондай-ақ Пайғамбардың ﷺ үмбетінен қате, ұмытшақтық және мәжбүрлік үшін жауапкершілікті алу туралы хадис (Ибн Мәжа 2043, хасан).\n\nМазхабтар фидияға осы қағиданы қолдануда алшақтайды: шафии мен ханбали мазхабтарының бір бөлігі нағыз ұмытшақтық немесе білместіктен туындаған бұзушылықтар үшін фидиядан босатады (аулау мен харам өсімдігін бүлдіру өтемінен басқа, онда фидия ниетке қарамастан талап етіледі, себебі бұл — тек қажының жеке міндеті емес, үшінші тараптың — тірі табиғат пен харамның құқығы), ал ханафи мен малики мазхабтары көп жағдайда фидияны ниетке қарамастан талап етеді, фидияның өзі күнә үшін жаза емес, ихрам күйін бұзғаны үшін өтем деп санайды.\n\nТәжірибе: бұзушылық кездейсоқ орын алса, тыйымды есіне түсірген немесе білген бойда әрекетті дереу тоқтатқан жөн (мысалы, тігілген киімді шешу, хош иісті жуып тастау), әрі нақты жағдайда фидия керек пе екенін өз мазхабына сай сүйемелдеуші алимнен нақтылаған жөн — мұнда барлық мектепке ортақ бірыңғай пікір жоқ.' },
      { title: 'Мытьё, купание и гигиена в ихраме', titleKk: 'Ихрамда жуыну және гигиена',
        detail: 'Паломнику в ихраме разрешено мыться, принимать душ и совершать полное омовение (гусль) обычной водой — это не считается нарушением, даже если при этом случайно выпадает несколько волосков или паломник почёсывает голову пальцами.\n\nХадис (⚠️ Бухари 1847, номер не подтверждён на 100%; Муслим 1205): сподвижники спросили Абдуллаха ибн Умара, можно ли мыть голову в ихраме, и он направил их к Абу Аюбу аль-Ансари, который рассказал, что видел, как Пророк ﷺ мылся в ихраме, поливая голову водой и потирая её руками, — прямое доказательство дозволенности мытья и лёгкого трения головы, при котором волосы могут выпасть непреднамеренно.\n\nЗапрещено именно намеренное удаление волос как отдельное действие (бритьё, выщипывание, стрижка) и использование ароматизированных средств — надушенного мыла, шампуня или зубной пасты с выраженным парфюмерным запахом; несильно ароматизированные гигиенические средства, которые не расцениваются как «нанесение благовония» в обычном понимании, по мнению многих современных учёных, допустимы, хотя более осторожная позиция — выбирать полностью нейтральные по запаху средства.\n\nПрактика: удобно взять с собой в поездку нейтральное (без запаха) мыло и зубную пасту заранее, чтобы не искать их в дороге; чистку зубов сиваком или щёткой без ароматизированной пасты ихрам не запрещает, это часть обычной гигиены, поощряемой сунной в любое время.',
        detailKk: 'Ихрамдағы қажыға әдеттегі сумен жуынуға, душ қабылдауға және толық дәрет алуға (ғұсыл) рұқсат етіледі — бұл кезде байқаусызда бірнеше шаш түсіп кетсе немесе қажы басын саусақпен қасыса да, бұзушылық саналмайды.\n\nХадис (⚠️ Бухари 1847, нөмірі толық расталмаған; Мүслім 1205): сахабалар Абдуллаһ ибн Омардан ихрамда бас жууға бола ма деп сұрағанда, ол оларды Әбу Әйюб әл-Ансариге жіберген, ол Пайғамбардың ﷺ ихрамда жуынғанын, басына су құйып, қолымен уқалағанын көргенін айтқан — бұл жуынуға және байқаусызда шаш түсуі мүмкін жеңіл уқалауға рұқсаттың тікелей дәлелі.\n\nТыйым салынғаны — дәл бөлек әрекет ретінде саналы шаш кетіру (қырыну, жұлу, қию) және хош иісті құралдарды (хош иісті сабын, шампунь немесе айқын хош иісі бар тіс пастасы) қолдану; көп қазіргі ғалымның пікірінше, әлсіз хош иісі бар, әдеттегі түсінікте «хош иіс жағу» деп саналмайтын гигиеналық құралдар рұқсат етіледі, дегенмен сақтырақ көзқарас — толық иіссіз құралдарды таңдау.\n\nТәжірибе: сапарға алдын ала иіссіз сабын мен тіс пастасын алып жүрген ыңғайлы, жолда іздемес үшін; сиуакпен немесе хош иісі жоқ щеткамен тіс тазалауды ихрам тыйым салмайды, бұл кез келген уақытта сүннетпен қолдау табатын әдеттегі гигиенаның бөлігі.' },
      { title: 'Фидья за нарушения', titleKk: 'Бұзғаны үшін фидия',
        detail: 'За срезание ногтей, удаление волос, парфюм, покрытие головы мужчиной — «фидья одного вида» на выбор: пост 3 дня, кормление 6 бедных, или заклание овцы (2:196, хадис Кааба ибн Уджры — ⚠️ Бухари 1814, номер не подтверждён на 100%; Муслим 1201). За охоту — компенсация подобным животным либо его стоимостью в еде или посте (5:95). За близость до первого снятия ограничений (тахаллюль авваль) хадж обычно не считается недействительным сразу, но требуется: продолжить все обряды, зарезать верблюда (бадана) и восполнить хадж на следующий год — по мнению большинства учёных.\n\nХадис Кааба ибн Уджры (⚠️ Бухари 1814, номер не подтверждён на 100%; Муслим 1201) — повод ниспослания аята 2:196: у Кааба на голове завелись вши от жары, и Пророк ﷺ велел ему обриться, предложив на выбор один из трёх видов фидьи, что стало универсальным правилом для подобных нарушений по нужде.\n\nФикх делит нарушения ихрама на три категории по типу воздаяния: (1) «фидья одного вида» — свободный выбор паломника между постом, кормлением и жертвой, для нарушений вроде срезания волос и парфюма; (2) компенсация, соразмерная ущербу, — для охоты и повреждения растительности харама, где размер определяют два справедливых свидетеля; (3) особая, более тяжёлая фидья с восполнением хаджа — только за половую близость до первого тахаллюля, единственное нарушение, ставящее под вопрос само действительность хаджа в этом году.\n\nПрактика: фидья одного вида выплачивается один раз за весь период непрерывного нарушения, а не за каждый день отдельно, по мнению большинства учёных; при сомнении, какая именно фидья требуется в конкретном случае, безопаснее сразу обратиться к сопровождающему алиму или в официальную службу фетв, доступную в сезон хаджа по телефону.',
        detailKk: 'Тырнақ алу, шаш кетіру, хош иіс жағу, ердің бас жабуы үшін — таңдау бойынша бір түрлі фидия: 3 күн ораза, 6 кедейді тамақтандыру, немесе қой сою (2:196 аяты, Кааб ибн Ужра хадисі — ⚠️ Бухари 1814, нөмірі толық расталмаған; Муслим 1201). Аулағаны үшін — соған ұқсас жануармен немесе оның құнына тең тамақ не ораза арқылы өтеу (5:95 аяты). Бірінші шектеуден босаудан (тахаллюль-и әууал) бұрын жақындық жасалса, хадж әдетте бірден жарамсыз болмайды, бірақ барлық ғибадатты жалғастыру, түйе (бадана) сою және келесі жылы хажды толтыру қажет — көп ғалымның пікірінше.\n\nКааб ибн Ужра хадисі (⚠️ Бухари 1814, нөмірі толық расталмаған; Мүслім 1201) — 2:196 аятының түсу себебі: Кааб ыстықтан басына бит түсіп кеткен, Пайғамбар ﷺ оған қырынуды бұйырып, үш түрлі фидияның бірін таңдауды ұсынған, бұл осындай мәжбүрлі бұзушылықтарға арналған әмбебап ережеге айналды.\n\nФикх ихрам бұзушылықтарын өтеу түріне қарай үш санатқа бөледі: (1) «бір түрлі фидия» — ораза, тамақтандыру және құрбандық арасында қажының еркін таңдауы, шаш кесу мен хош иіс жағу сияқты бұзушылықтар үшін; (2) зиянға сай өтем — аулау және харам өсімдігін бүлдіру үшін, мұнда мөлшерді екі әділ куә анықтайды; (3) хажды толтырумен бірге келетін ерекше, ауырырақ фидия — тек бірінші тахаллюльден бұрынғы жыныстық жақындық үшін, бұл осы жылғы хаждың жарамдылығын күмәнге қалдыратын жалғыз бұзушылық.\n\nТәжірибе: бір түрлі фидия үздіксіз бұзушылықтың бүкіл кезеңі үшін бір рет төленеді, әр күн үшін бөлек емес — көп ғалымның пікірінше; нақты жағдайда қандай фидия керектігіне күмән болса, сүйемелдеуші алимге немесе хадж маусымында телефон арқылы қолжетімді ресми фетуа қызметіне тікелей хабарласқан қауіпсіз.' }
    ];

    const HAJJ_WOMEN = [
      { title: 'Махрам', titleKk: 'Махрам',
        detail: 'По мнению большинства учёных, женщина отправляется в хадж только в сопровождении махрама (мужа или близкого родственника, за которого ей запрещён брак). Подробнее — см. вкладку «Условия».\n\nСтепень родства махрама строго определена шариатом (отец, муж, сын, брат, дядя и подобные, за кого запрещён брак навсегда) — просто доверенный друг семьи или дальний знакомый мужчина не считается махрамом, даже при полном доверии семьи.\n\nХадис (Бухари 1088, Муслим 1341): Пророк ﷺ сказал: «Пусть женщина не отправляется в путь длительностью более суток иначе как с махрамом». Большинство ханафитских и маликитских учёных считают это условие обязательным для действительности хаджа как таковое, тогда как часть шафиитских и ханбалитских факихов, а также современные фетвы ряда авторитетных советов допускают выезд на обязательный хадж в составе надёжной группы женщин («сафар аль-джама‘а») при доказанной безопасности маршрута — подробнее см. новую карточку «Путешествие без махрама — современные подходы» ниже.\n\nПрактика: заранее оформить документы, подтверждающие родство с сопровождающим, для визовых и организационных нужд саудовских властей — устного заявления может быть недостаточно.',
        detailKk: 'Көп ғалымның пікірінше, нәзік жанды хаджға тек махраммен (күйеуі немесе некесі харам жақын туысы) барады. Толығырақ — «Шарттар» бөлімін қараңыз.\n\nМахрамның туыстық дәрежесі шариғатта қатаң белгіленген (әке, күйеу, ұл, аға-іні, ағай-нағашы және мәңгі некесі харам ұқсас туыстар) — отбасының толық сенімі болса да, жай сенімді отбасы досы немесе алыстау таныс ер адам махрам саналмайды.\n\nХадис (Бухари 1088, Муслим 1341): Пайғамбар ﷺ: «Нәзік жанды бір тәуліктен астам жол жүрсе, махрамсыз жүрмесін» деген. Ханафи және малики мазһабының көп ғалымы бұл шартты хаждың жарамдылығына міндетті деп санайды, ал шафии және ханбали факихтерінің бір бөлігі, сондай-ақ бірқатар беделді фетуа кеңестерінің қазіргі фетуалары жол қауіпсіздігі дәлелденсе, парыз хажға сенімді нәзік жандылар тобымен («сафар әл-жама‘а») шығуға рұқсат етеді — толығырақ төмендегі «Махрамсыз саяхат — қазіргі көзқарастар» жаңа карточкасын қараңыз.\n\nТәжірибе: сауд билігінің виза және ұйымдастыру қажеттіліктері үшін сүйемелдеушімен туыстықты растайтын құжаттарды алдын ала дайындаңыз — ауызша мәлімдеу жеткіліксіз болуы мүмкін.' },
      { title: 'Хайд и нифас во время хаджа', titleKk: 'Хаждда хайыз бен нифас',
        detail: 'Менструация или послеродовое кровотечение не мешают большинству обрядов хаджа — можно быть в ихраме, ехать на Арафат, ночевать в Муздалифе и Мине, участвовать во всём, кроме тавафа вокруг Каабы. Хадис Аиши (р.а.): Пророк ﷺ сказал ей во время месячных: «Делай всё, что делает совершающий хадж, кроме тавафа вокруг Дома, пока не очистишься» (Бухари 305, Муслим 1211). Таваф откладывается до очищения.\n\nЭтот же хадис (Бухари 305) продолжается словами Аиши (р.а.): она была в состоянии хайда во время прощального хаджа и совершила все обряды, кроме тавафа, а очистившись перед отъездом — таваф ифада уже в чистоте.\n\nХадис (Ибн Аббас, Бухари 1758, Муслим 1211): когда сподвижники спросили Пророка ﷺ о выезде женщины в состоянии хайда без прощального тавафа, он сказал: «Пусть она уезжает» — то есть прощальный таваф (таваф аль-вада‘) снимается с неё в этом состоянии, в отличие от тавафа ифада (одного из столпов хаджа), который отложить нельзя и который обязательно нужно выполнить после очищения, даже если для этого придётся вернуться отдельно.\n\nПрактика: если очищение наступает уже после отъезда каравана домой, женщина остаётся в состоянии частичного ихрама до возвращения и совершения тавафа — на практике редко выполнимо, поэтому многие заранее советуются о приёме препаратов, сдвигающих цикл (см. следующую карточку).',
        detailKk: 'Хайыз немесе босанғаннан кейінгі қан кету хаждың көп ғибадатына кедергі жасамайды — ихрамда болуға, Арафатқа баруға, Муздалифа мен Минада түнеуге, Қағбаны тауаф етуден басқасына қатысуға болады. Аиша (р.а.) хадисі: Пайғамбар ﷺ оған хайыз кезінде: «Тазармайынша, Үйді тауаф етуден басқа, хажы жасайтын нәрсенің бәрін жаса» деген (Бухари 305, Муслим 1211). Тауаф тазарғанға дейін кейінге қалдырылады.\n\nДәл осы хадис (Бухари 305) Аишаның (р.а.) сөздерімен жалғасады: ол қоштасу хажында хайыз күйінде болған және тауафтан басқа барлық ғұрыпты орындаған, ал аттанар алдында тазарып, тауаф ифаданы таза күйінде жасаған.\n\nХадис (Ибн Аббас, Бухари 1758, Муслим 1211): сахабалар Пайғамбардан ﷺ хайыз күйіндегі нәзік жандының қоштасу тауафысыз кетуі туралы сұрағанда, ол: «Кете берсін» деген — яғни қоштасу тауафы (тауаф әл-уада‘) тазармаған нәзік жандыдан алынып тасталады, ал тауаф ифада (хаждың тіректерінің бірі) кейінге қалдырылмайды және тазарғаннан кейін міндетті түрде орындалуы керек, тіпті сол үшін бөлек қайта оралуға тура келсе де.\n\nТәжірибе: тазару керуен үйге аттанғаннан кейін ғана орын алса, нәзік жанды қайтып, тауафты орындағанға дейін жартылай ихрам күйінде қалады — іс жүзінде сирек орындалады, сондықтан көптер циклды жылжытатын дәрі қабылдау туралы алдын ала кеңеседі (келесі карточканы қараңыз).' },
      { title: 'Задержка цикла лекарствами', titleKk: 'Дәрімен циклды кейінге қалдыру',
        detail: 'Чтобы облегчить выполнение тавафа ифада в срок, некоторые современные учёные разрешают приём препаратов, сдвигающих цикл, по предварительной консультации с врачом — это вопрос иджтихада, не единогласное правило, желательно решить заранее до поездки.\n\nПринцип, на который опираются такие фетвы, — общее правило облегчения (рухса) при затруднении в шариате, а приём подобных препаратов не относится к прямым текстовым запретам, а является вопросом иджтихада по аналогии с иными формами регулирования организма, уже дозволенными в фикхе.\n\nПрактика: препараты рекомендуется начинать заранее, минимум за 1–2 недели, под контролем врача, поскольку резкая гормональная перестройка перед интенсивной физической нагрузкой хаджа может плохо переноситься.\n\nЕсли, несмотря на приём препаратов, кровотечение всё же продолжается в дни обрядов, часть учёных рассматривает эту ситуацию как истихаду (патологическое, а не менструальное кровотечение) — в этом случае женщина совершает гусль перед тавафом, использует гигиеническую защиту и выполняет обряд, не откладывая таваф, подобно человеку с постоянным малым осквернением; этот вопрос лучше решать на месте с сопровождающей знающей женщиной или факихом, поскольку оценка ситуации индивидуальна.',
        detailKk: 'Тауаф ифаданы уақытында орындауды жеңілдету үшін кейбір қазіргі ғалымдар алдын ала дәрігермен келісіп, циклды жылжытатын дәрі қабылдауға рұқсат етеді — бұл ижтихад мәселесі, бірауыздан келісілген ереже емес, сапарға дейін алдын ала шешкен жөн.\n\nМұндай фетуалар сүйенетін қағида — шариғаттағы қиындық кезіндегі жалпы жеңілдік (рухса) ережесі, мұндай дәрі қабылдау тікелей мәтіндік тыйымдарға жатпайды, фикхте бұрыннан рұқсат етілген ағзаны реттеудің басқа түрлеріне ұқсастық бойынша ижтихад мәселесі болып табылады.\n\nТәжірибе: дәрілерді алдын ала, кемінде 1–2 апта бұрын, дәрігердің бақылауымен бастаған жөн, себебі хаждың қарқынды дене жүктемесінің алдында кенеттен гормоналдық өзгеріс нашар қабылдануы мүмкін.\n\nДәрі қабылдағанына қарамастан, қан кету ғұрып күндерінде жалғасса, кейбір ғалымдар мұны истихада (хайыз емес, патологиялық қан кету) деп қарастырады — бұл жағдайда нәзік жанды тауафтан бұрын ғұсыл алады, гигиеналық қорғаныс құралын пайдаланады және тауафты кейінге қалдырмай, үздіксіз шағын тазасыздық күйіндегідей ғұрыпты орындайды; бұл мәселені жергілікті жерде сүйемелдеуші білікті нәзік жанды немесе факихпен шешкен дұрыс, себебі жағдайды бағалау әрқайсысына жеке қаралады.' },
      { title: 'Одежда', titleKk: 'Киім',
        detail: 'Обычная скромная одежда любого цвета, закрывающая тело и волосы; лицо и кисти рук открыты, кроме случаев присутствия посторонних мужчин (см. вкладку «Ихрам»). Специального «женского ихрама» с определённым цветом или покроем в шариате нет.\n\nВ отличие от мужского ихрама, для которого чётко предписаны материал (несшитая ткань) и предпочтительный белый цвет, для женской одежды в хадже шариат не устанавливает ни цвета, ни кроя — единственное условие: обычные нормы хиджаба, применимые к женщине в любой другой ситуации при посторонних мужчинах.\n\nПрактика: многие женщины предпочитают светлую, немаркую и удобную одежду свободного кроя — это вопрос удобства и местного обычая, а не отдельного шариатского предписания.\n\nВ отличие от мужчин, которым разрешено умащаться благовониями перед ихрамом даже с сильным ароматом, женщине в ихраме (а по мнению многих учёных — и в обычной жизни при выходе к посторонним мужчинам) следует избегать интенсивных парфюмерных ароматов, привлекающих внимание, — это связано не с запретами ихрама как такового, а с общими нормами скромности (хайа), особенно уместными в местах большого скопления людей.',
        detailKk: 'Денені және шашты жабатын, кез келген түстегі қарапайым, әдепті киім; бет пен қол ашық, тек бөгде ер адамдар болғанда ғана жабылады («Ихрам» бөлімін қараңыз). Шариғатта белгілі түсі немесе пішіні бар арнайы «нәзік жанды ихрамы» жоқ.\n\nЕрлер ихрамынан айырмашылығы, оған материал (тігілмеген мата) және артықшылықты ақ түс нақты белгіленген, хаждағы нәзік жанды киіміне шариғат түс те, пішін де белгілемейді — жалғыз шарт: бөгде ер адамдар болған кез келген басқа жағдайда нәзік жандыға қолданылатын әдеттегі хиджаб нормалары.\n\nТәжірибе: көптеген нәзік жандылар ашық түсті, кірлемейтін, ыңғайлы, еркін пішінді киімді таңдайды — бұл ыңғайлылық пен жергілікті әдет мәселесі, бөлек шариғи нұсқау емес.\n\nЕрлерге қарағанда — оларға ихрамнан бұрын күшті хош иіспен майлануға рұқсат етіледі — ихрамдағы нәзік жандыға (көп ғалымның пікірінше, тіпті күнделікті өмірде бөгде ер адамдардың алдына шыққанда да) назар аудартатын қатты парфюм иісінен аулақ болған жөн — бұл мәселе ихрамның өзіндік тыйымдарына емес, әдептілік (хайа) жалпы нормаларына байланысты, әсіресе адам көп жиналатын жерлерде маңызды.' },
      { title: 'Безопасность в толпе', titleKk: 'Тобырдағы қауіпсіздік',
        detail: 'По возможности выбирать менее людные часы для тавафа и побития камней (раннее утро, поздняя ночь), не отделяться от группы, держать при себе данные сопровождающего и место сбора на случай, если потерялись.\n\nЭто часть общего принципа сохранения жизни (хифз ан-нафс) — одной из пяти базовых ценностей шариата, ради защиты которой дозволены разумные предосторожности, вплоть до временного облегчения некоторых действий обряда (например, замены личного побития камней доверенным лицом при реальной угрозе давки).\n\nПрактика: держать при себе браслет или карточку с именем, номером группы и телефоном сопровождающего, выучить название и номер своего лагеря в Мине.\n\nВ отдельные периоды организаторы хаджа выделяют менее загруженные часы или отдельные полосы движения для женщин, пожилых и людей с инвалидностью при тавафе и побитии камней — это расписание стоит уточнять у сопровождающей группы на месте, поскольку правила могут меняться год от года в зависимости от общей загруженности.',
        detailKk: 'Мүмкіндігінше тауаф пен тас лақтыруға адам азырақ уақытты таңдау (таңертең ерте, түн ортасы), топтан алшақтамау, адасып қалған жағдайға арналған сүйемелдеушінің деректері мен жиналу орнын өзінде сақтау.\n\nБұл өмірді сақтаудың жалпы қағидасының (хифз ан-нафс) бір бөлігі — шариғаттың бес негізгі құндылығының бірі, оны қорғау үшін ақылға қонымды сақтық шаралары, тіпті ғұрыптың кейбір әрекеттерін уақытша жеңілдету (мысалы, нақты кептеліс қаупі болғанда өз тас лақтыруын сенімді адамға ауыстыру) рұқсат етіледі.\n\nТәжірибе: өзіңізбен бірге аты-жөні, топ нөмірі және сүйемелдеушінің телефоны жазылған білезік немесе карточка алып жүріңіз, Минадағы өз лагеріңіздің атауы мен нөмірін жаттап алыңыз.\n\nКейбір кезеңдерде хажды ұйымдастырушылар тауаф пен тас лақтыру кезінде нәзік жандыларға, қарттарға және мүгедектігі бар адамдарға арналған адам азырақ уақыт немесе бөлек жолақ бөледі — бұл кестені жергілікті жерде сүйемелдеуші топтан нақтылаған жөн, себебі ережелер жүктеменің жалпы деңгейіне байланысты жылдан-жылға өзгеруі мүмкін.' },
      { title: 'Путешествие без махрама — современные подходы', titleKk: 'Махрамсыз саяхат — қазіргі көзқарастар',
        detail: 'Классическое условие большинства мазхабов — обязательное сопровождение махрама в хадже. Однако в случаях, где риск в пути минимален (организованные авиаперелёты, охраняемые группы, государственный контроль маршрута), часть современных муфтиев и фетва-советов допускает выезд женщины на обязательный хадж в составе надёжной группы других женщин («сафар аль-джама‘а») или под опекой ответственного лица, даже без личного махрама, — это мнение восходит к некоторым шафиитским и отдельным ханбалитским факихам, считавшим главным условием безопасность пути (амн ат-тарик), а не обязательно родство сопровождающего.\n\nХадис, на который опираются сторонники строгого условия махрама (Бухари 1088, Муслим 1341): «Пусть женщина не отправляется в путь иначе как с махрамом» — большинство ханафитских и маликитских учёных применяют его буквально к любой поездке протяжённостью, требующей сокращения молитвы, независимо от степени организованности и безопасности маршрута.\n\nПрактика: перед поездкой стоит уточнить конкретное решение духовного управления своей страны — в некоторых странах организованный государством хадж в составе женской группы официально признаётся допустимой заменой махрама, в других требование сохраняется в полном объёме.',
        detailKk: 'Көп мазһабтың классикалық шарты — хаждда махрамның міндетті түрде сүйемелдеуі. Дегенмен жолда қауіп ең аз болатын жағдайларда (ұйымдастырылған авиарейстер, күзетілетін топтар, мемлекеттің маршрутты бақылауы) кейбір қазіргі мүфтилер мен фетуа кеңестері нәзік жандыға парыз хажға басқа сенімді нәзік жандылар тобымен («сафар әл-жама‘а») немесе жауапты адамның қамқорлығымен, тіпті жеке махрамсыз шығуға рұқсат етеді — бұл пікір қауіпсіз жолды (амн ат-тарик) негізгі шарт деп санаған кейбір шафии және жекелеген ханбали факихтеріне барып тіреледі, ал сүйемелдеушінің туыстығы міндетті емес.\n\nМахрам шартын қатаң ұстанушылар сүйенетін хадис (Бухари 1088, Муслим 1341): «Нәзік жанды махрамсыз жол жүрмесін» — ханафи және малики ғалымдарының көбі мұны ұйымдастырылу мен қауіпсіздік дәрежесіне қарамастан, намазды қысқартуды талап ететін кез келген сапарға тура мағынасында қолданады.\n\nТәжірибе: сапар алдында өз еліңіздің діни басқармасының нақты шешімін білген жөн — кейбір елдерде мемлекет ұйымдастырған, нәзік жандылар тобымен жасалатын хадж махрамның ресми баламасы ретінде танылады, басқаларында талап толық күшінде қалады.' },
      { title: 'Беременность, роды и кормление грудью', titleKk: 'Жүктілік, босану және емшек емізу',
        detail: 'Беременность сама по себе не мешает совершению хаджа и умры, если врач подтверждает отсутствие противопоказаний к длительным переездам, интенсивной ходьбе и большим скоплениям людей — решение о поездке стоит принимать совместно с наблюдающим гинекологом, особенно в первом и третьем триместре.\n\nЕсли роды или сильное кровотечение (нифас) наступают уже во время хаджа, действуют те же правила, что и при хайде: женщина в нифасе может входить в ихрам, стоять на Арафате и участвовать во всех обрядах, кроме тавафа, который откладывается до очищения или прекращения кровотечения (Бухари 305, Муслим 1211, по аналогии с хайдом, на что указывают ханафитские и шафиитские факихи).\n\nКормящей женщине разрешено совершать хадж и умру без ограничений, связанных именно с кормлением, — если долгая разлука с ребёнком нежелательна, современные фетвы допускают взять ребёнка с собой при организационной возможности или отложить необязательный (сверхнормовый) хадж/умру до более удобного времени, оставив в силе только обязательный хадж при наличии истита‘а.\n\nПрактика: перед поездкой на любом сроке беременности желательно получить письменное медицинское заключение о допустимости перелёта и физической нагрузки — авиакомпании и организаторы хаджа нередко требуют его на определённых сроках беременности.',
        detailKk: 'Дәрігер ұзақ жол жүруге, қарқынды жаяу жүруге және адам көп жиналатын жерлерге қарсы көрсетілім жоқ деп растаса, жүктілік хадж бен умраны орындауға өз алдына кедергі емес — сапар туралы шешімді бақылап отырған гинекологпен бірге, әсіресе бірінші және үшінші триместрде, қабылдаған жөн.\n\nБосану немесе күшті қан кету (нифас) хадж кезінде басталса, хайыздағыдай ережелер қолданылады: нифастағы нәзік жанды ихрамға кіре алады, Арафатта тұра алады және тауафтан басқа барлық ғұрыпқа қатыса алады, ал тауаф тазарғанға немесе қан кету тоқтағанға дейін кейінге қалдырылады (Бухари 305, Муслим 1211, хайызбен ұқсастық бойынша, мұны ханафи және шафии факихтері көрсетеді).\n\nЕмшек емізетін нәзік жандыға хадж бен умраны тек емізумен байланысты шектеусіз орындауға рұқсат етіледі — баламен ұзақ айырылысу қалаусыз болса, қазіргі фетуалар ұйымдастыру мүмкіндігі болғанда баланы бірге алуға немесе истиғаат бар парыз хаждды сақтап, міндетті емес (артық) хадж/умраны қолайлырақ уақытқа қалдыруға рұқсат етеді.\n\nТәжірибе: жүктіліктің кез келген мерзімінде сапарға дейін ұшу мен дене жүктемесінің рұқсат етілетіні туралы жазбаша медициналық қорытынды алған жөн — авиакомпаниялар мен хаж ұйымдастырушылары жүктіліктің белгілі бір мерзімінде оны жиі талап етеді.' }
    ];

    const HAJJ_FAQ = [
      { title: 'Можно ли совершить хадж за другого (хадж бадаль)?', titleKk: 'Басқа адам үшін хадж жасауға бола ма (хадж бадал)?',
        detail: 'Да — за умершего или неспособного передвигаться (тяжелобольного, очень пожилого) человека, при условии что исполняющий уже совершил свой собственный обязательный хадж. Хадис: женщина спросила Пророка ﷺ о хадже за отца, который не может держаться на верблюде, — он ответил: «Соверши хадж за него» (Бухари 1854, Муслим 1334).\n\nУчёные уточняют дополнительные условия хадж бадаль: исполняющий произносит намерение именно за того, кого замещает («Ляббайка ан фулян» — «Вот я перед Тобой за такого-то»), а не за себя; жертвоприношение и фидья, если потребуются, оплачиваются из средств замещающего или доверителя по договорённости.\n\nПрактика: перед оплатой услуги хадж бадаль через агентство стоит убедиться в его надёжности — известны случаи, когда деньги собираются, но хадж за умершего фактически не совершается.\n\nПравило распространяется и на умру: за умершего или неспособного человека допустимо совершить умру бадаль на тех же условиях, что и хадж бадаль. Если человек умер, уже имея финансовую возможность (истита‘а) для хаджа, но не успел его совершить, большинство учёных считают хадж бадаль за него обязательным и оплачиваемым из оставленного им наследства, ещё до раздела имущества между наследниками — подобно другому долгу умершего.',
        detailKk: 'Иә — қайтыс болған немесе жүре алмайтын (ауыр науқас, өте кәрі) адам үшін, орындаушы адам өзінің парыз хажын бұрын жасаған болса. Хадис: бір нәзік жанды түйеде отыра алмайтын әкесі үшін сұрағанда, Пайғамбар ﷺ: «Оның атынан хадж жаса» деп жауап берген (Бухари 1854, Муслим 1334).\n\nҒалымдар хадж бадалдың қосымша шарттарын нақтылайды: орындаушы дәл кімнің орнына жасап жатқаны туралы ниет айтады («Ляббайка ан фулян» — «Мінеки мен Сенің алдыңдамын пәленшенің орнына»), өзі үшін емес; құрбандық пен фидия, қажет болса, орындаушының немесе тапсырыс берушінің қаражатынан келісім бойынша төленеді.\n\nТәжірибе: агенттік арқылы хадж бадал қызметін төлеу алдында оның сенімділігіне көз жеткізген жөн — ақша жиналғанымен, қайтыс болған адам үшін хадж іс жүзінде жасалмаған жағдайлар белгілі.\n\nБұл ереже умраға да қолданылады: қайтыс болған немесе жасай алмайтын адам үшін хаж бадалмен бірдей шарттармен умра бадал жасауға болады. Адам хаж үшін қаржылық мүмкіндігі (истиғаат) болып тұрып, оны орындамай қайтыс болса, көп ғалым оның атынан хаж бадалды міндетті деп санайды және оны мұрагерлерге бөлінбей тұрып, қалдырған мұрасынан төлеу керек — қайтыс болған адамның басқа қарызы сияқты.' },
      { title: 'Что если пропустил обязательное действие?', titleKk: 'Парыз әрекетті орындамай қалса ше?',
        detail: 'Пропуск столпа (Арафат, таваф ифада, ихрам) делает хадж недействительным — по мнению большинства учёных требуется повторить его в другой год. Пропуск обязанности (ваджиб, не столп — например, ночёвка в Муздалифе или Мине) обычно восполняется фидьей (жертвой или постом), сам хадж остаётся действительным.\n\nФикх различает три уровня действий хаджа: столпы (аркан — Арафат, таваф ифада, ихрам, по некоторым мазхабам и са‘и), обязанности (ваджибат — например, ночёвка в Муздалифе и Мине, побитие камней, таваф прощания) и сунны — пропуск сунны не требует ничего, ваджиба — восполняется фидьей, а столпа делает хадж недействительным.\n\nПрактика: при сомнении, что именно было пропущено, стоит обратиться к сопровождающему учёному ещё до отъезда домой — большинство вопросов проще решить на месте.\n\nОсобый случай — ихсар (вынужденная блокировка от завершения обрядов из-за болезни, войны, закрытия границы или иного непреодолимого препятствия): Коран (2:196) указывает, что в этом случае паломник приносит в жертву то животное, что доступно, и выходит из состояния ихрама, не завершив хадж, без необходимости платить дополнительную фидью, — обязательный хадж при этом нужно будет совершить позже, когда появится возможность.',
        detailKk: 'Тіректі (Арафат, тауаф ифада, ихрам) қалдырып кету хажды жарамсыз етеді — көп ғалымның пікірінше, оны басқа жылы қайталау керек. Уәжібті (тірек емес — мысалы, Муздалифа немесе Минада түнеу) орындамау әдетте фидиямен (құрбандық немесе ораза) толтырылады, хаждың өзі жарамды қалады.\n\nФикх хадж әрекеттерінің үш деңгейін ажыратады: тіректер (аркан — Арафат, тауаф ифада, ихрам, кейбір мазһабтар бойынша сағи де), уәжіптер (ваджибат — мысалы, Муздалифа мен Минада түнеу, тас лақтыру, қоштасу тауафы) және сүннеттер — сүннетті қалдырып кету ешнәрсе талап етпейді, уәжіпті — фидиямен толтырылады, ал тіректі қалдырса хадж жарамсыз болады.\n\nТәжірибе: не қалдырылғанына күмән болса, үйге аттанбай тұрып сүйемелдеуші ғалымға хабарласқан жөн — көп мәселені сол жерде шешкен оңайырақ.\n\nЕрекше жағдай — ихсар (ауру, соғыс, шекараның жабылуы немесе басқа еңсерілмейтін кедергі салдарынан ғұрыпты аяқтаудан мәжбүрлі бөгелу): Құран (2:196) бұл жағдайда қажы қолда бар малды құрбандыққа шалып, хаждды аяқтамай-ақ ихрамнан шыға алатынын, қосымша фидия төлеудің қажеті жоқ екенін көрсетеді — парыз хаж кейін, мүмкіндік туғанда қайта орындалуы керек.' },
      { title: 'Хадж в долг — обязателен ли?', titleKk: 'Қарызға хадж жасау — парыз ба?',
        detail: 'Нет. Одно из условий истита‘а — не влезать в долг, который ухудшит положение семьи. Большинство учёных не рекомендуют брать кредит специально ради хаджа, если это создаёт финансовое бремя; при наличии такой возможности без вреда для семьи — решение остаётся за самим человеком.\n\nПринцип, лежащий в основе такого подхода фикха, — общее правило приоритета возврата долгов перед добровольными и даже некоторыми обязательными по обстоятельствам тратами, поскольку долг — это право конкретного человека (хакк аль-ибад), а откладывание хаджа при отсутствии истита‘а не является грехом.\n\nПрактика: если долг с фиксированным сроком выплаты уже есть, приоритет — погасить его, а не тратить свободные средства на хадж; если истита‘а уже наступила до возникновения долга, ситуация иная и требует консультации со знающим.\n\nЕсли рассматриваемый кредит является процентным (риба), он запрещён в шариате независимо от цели, включая хадж, — брать такой кредит специально ради паломничества недопустимо ни при каких обстоятельствах, и это отдельный, более строгий запрет, не связанный напрямую с условием истита‘а.',
        detailKk: 'Жоқ. Істиғаат шарттарының бірі — отбасының жағдайын нашарлататын қарызға бармау. Көп ғалым қаржылық ауыртпалық түсірсе, хадж үшін арнайы несие алуды ұсынбайды; отбасына зиян келтірмейтін мүмкіндік болса — шешім адамның өзіне қалады.\n\nФикхтың мұндай көзқарасының негізінде жатқан қағида — қарызды қайтаруды ерікті және тіпті жағдайға байланысты кейбір міндетті шығындардан бұрын қою туралы жалпы ереже, себебі қарыз — нақты адамның құқығы (хакк әл-ибад), ал істиғаат болмағанда хаждды кейінге қалдыру күнә емес.\n\nТәжірибе: белгілі бір мерзімі бар қарыз бар болса, оны өтеу — басымдық, бос қаражатты хаджға жұмсаудан гөрі; істиғаат қарыз пайда болғанға дейін туындаса, жағдай өзгеше, білетін адаммен ақылдасу қажет.\n\nЕгер қарастырылып отырған несие пайыздық (риба) болса, ол мақсатына қарамастан, соның ішінде хажға да, шариғатта тыйым салынған — мұндай несиені арнайы қажылық үшін алу ешбір жағдайда жол берілмейді, бұл истиғаат шартымен тікелей байланысты емес, бөлек және қатаңырақ тыйым.' },
      { title: 'Нужно ли ждать очереди или квоты?', titleKk: 'Кезек немесе квотаны күту керек пе?',
        detail: 'В большинстве стран хадж регулируется государственными квотами и организованными группами через официальные турагентства и духовные управления — самостоятельный въезд для хаджа без разрешения затруднён и в ряде случаев запрещён властями Саудовской Аравии. Уточняйте актуальные правила у официального представителя духовного управления вашей страны.\n\nСовременная система квот (введена властями Саудовской Аравии в 1987 году по соглашению стран-членов ОИС, обычно из расчёта примерно 1 паломник на 1000 мусульман населения страны) относится к вопросам сийаса шар‘ия (административного управления в рамках шариата) — учёные признают право государства регулировать порядок массового паломничества ради предотвращения давки и жертв.\n\nПрактика: заявку на хадж через официальную квоту своей страны стоит подавать заблаговременно, а параллельно рассматривать умру как духовную альтернативу на время ожидания.\n\nВизы для хаджа и умры оформляются отдельно и по разным правилам: виза умры обычно доступна круглый год через турагентства без государственной квоты страны, тогда как виза хаджа жёстко привязана к национальной квоте и сезону — приезд в Саудовскую Аравию по визе умры с целью самостоятельно остаться на хадж без соответствующего разрешения запрещён властями и может повлечь депортацию и запрет на въезд в будущем.',
        detailKk: 'Көп елде хадж мемлекеттік квота және ресми турагенттіктер мен діни басқармалар арқылы ұйымдастырылған топтармен реттеледі — рұқсатсыз өз бетінше хаждға кіру қиын, кейбір жағдайда Сауд Арабиясы билігі тыйым салады. Еліңіздің ресми діни басқармасынан ағымдағы ережелерді нақтылаңыз.\n\nҚазіргі квота жүйесі (Сауд Арабиясы билігі 1987 жылы ЫЫҰ мүше елдерінің келісімімен енгізген, әдетте елдің шамамен әр 1000 мұсылманына 1 қажы есебінен) сийаса шариия (шариғат аясындағы әкімшілік басқару) мәселелеріне жатады — ғалымдар кептеліс пен құрбандарды болдырмау үшін мемлекеттің жаппай қажылықты реттеу құқығын мойындайды.\n\nТәжірибе: өз еліңіздің ресми квотасы арқылы хажға өтінімді алдын ала беру керек, ал күту кезінде умраны рухани балама ретінде қарастыруға болады.\n\nХадж пен умраның визалары бөлек және әртүрлі ережемен рәсімделеді: умра визасы әдетте жыл бойы, елдің мемлекеттік квотасынсыз турагенттіктер арқылы қолжетімді, ал хадж визасы ұлттық квотаға және маусымға қатаң байланысты — умра визасымен Сауд Арабиясына келіп, тиісті рұқсатсыз өз бетінше хажға қалу билік тарапынан тыйым салынған және болашақта депортация мен елге кіруге тыйым салуға әкелуі мүмкін.' },
      { title: 'Хадж несовершеннолетнего ребёнка', titleKk: 'Кәмелетке толмаған баланың хажы',
        detail: 'Ребёнок может участвовать в хадже вместе с родителями или опекуном, и этот хадж засчитывается ему как добровольный (нафль) — известен случай, когда женщина подняла ребёнка на руках и спросила Пророка ﷺ, засчитывается ли это как хадж, на что он ответил: «Да, и тебе за это награда» (Муслим 1336).\n\nДетский хадж, даже совершённый полностью и правильно, не освобождает человека от обязательного хаджа после достижения совершеннолетия и появления финансовой возможности (истита‘а) — по единогласному мнению факихов, обязательный хадж нужно будет совершить заново уже во взрослом возрасте.\n\nЗа ребёнка, не способного самостоятельно выполнить обряд (например, побитие камней), опекун совершает действие от его имени, держа символический камень его рукой либо бросая камень за него, в зависимости от возраста и физических возможностей малыша.\n\nПрактика: длительные переезды, жара и большие скопления людей на хадже создают серьёзную физическую и санитарную нагрузку для маленьких детей — вопрос о взятии ребёнка с собой стоит взвешивать не только с точки зрения фикха, но и практической безопасности и здоровья.',
        detailKk: 'Бала ата-анасымен немесе қамқоршысымен бірге хажға қатыса алады, және бұл оған ерікті (нәфл) хадж ретінде есептеледі — бір нәзік жанды баланы қолына көтеріп, Пайғамбардан ﷺ бұл хадж болып есептеле ме деп сұрағанда, ол: «Иә, және саған сауап бар» деп жауап берген (Муслим 1336).\n\nБаланың хажы, тіпті толық және дұрыс орындалса да, кәмелетке толып, қаржылық мүмкіндік (истиғаат) пайда болғаннан кейін адамды парыз хаждан босатпайды — факихтердің бірауызды пікірі бойынша, парыз хаж ересек кезде қайта орындалуы керек.\n\nҒұрыпты өз бетінше орындай алмайтын балаға (мысалы, тас лақтыру) қамқоршы бала жасына және дене мүмкіндігіне қарай оның қолымен тас лақтырады немесе оның орнына лақтырады.\n\nТәжірибе: хаждағы ұзақ сапар, ыстық және адамның көп жиналуы кішкентай балаларға дене және санитарлық тұрғыдан ауыр жүктеме түсіреді — баланы бірге алу мәселесін тек фикх тұрғысынан ғана емес, іс жүзіндегі қауіпсіздік пен денсаулық тұрғысынан да өлшеген жөн.' },
      { title: 'Сколько раз можно совершать умру за одну поездку', titleKk: 'Бір сапарда неше рет умра жасауға болады',
        detail: 'Число умр за одну поездку в шариате не ограничено — по мнению большинства учёных, повторная умра дозволена в любое время, кроме периода самого хаджа (между входом в ихрам хаджа и выходом из него). Пророк ﷺ сам совершил несколько умр за годы своей жизни в разное время.\n\nОднако часть учёных, включая некоторых маликитских факихов, считает нежелательным (макрух) совершать несколько умр подряд за одну короткую поездку без разумного перерыва (например, выезд из Мекки в ближайший микат и немедленное возвращение только ради нового ихрама умры) — это мнение опирается на то, что сподвижники и табиины такой практики массово не придерживались, а сама умра — не обряд, который стоит механически повторять как ритуал ради количества.\n\nПрактика: тем, кто приезжает в Мекку на длительный срок, разумнее ограничиться одной-двумя умрами и посвятить оставшееся время дополнительным молитвам, чтению Корана и тавафу, а не многократному циклу выезда к микату исключительно ради формального умножения числа умр.',
        detailKk: 'Бір сапардағы умра санына шариғатта шек қойылмаған — көп ғалымның пікірінше, хаждың өз кезеңінен (хадж ихрамына кіргеннен шыққанға дейін) басқа кез келген уақытта қайталап умра жасауға болады. Пайғамбар ﷺ өз өмірінде бірнеше рет, әртүрлі уақытта умра жасаған.\n\nДегенмен кейбір ғалымдар, соның ішінде бірқатар малики факихтері, қысқа бір сапарда ақылға қонымды үзіліссіз бірнеше умраны қатарынан жасауды (мысалы, Мәккеден жақын микатқа шығып, тек жаңа умра ихрамы үшін бірден қайту) макрух деп санайды — бұл пікір сахабалар мен табииндердің мұндай тәжірибені жаппай ұстанбағанына, ал умраның өзі санды көбейту үшін механикалық түрде қайталанатын ғұрып емес екеніне сүйенеді.\n\nТәжірибе: Мәккеге ұзақ мерзімге келгендерге бір-екі умрамен шектеліп, қалған уақытты қосымша намаз, Құран оқу және тауафқа арнаған дұрыс, тек микатқа шығып қайтудың көп циклын умра санын формальды түрде көбейту үшін жасамаған жөн.' }
    ];

